def countdown(seconds, background=False):
    """Display a countdown timer in the terminal."""
    try:
        total = int(seconds)
        if total <= 0:
            total = 10
    except ValueError:
        total = 10

    log_timer(total)
    log_usage_patterns(total, background)

    if not background:
        print(f"Starting timer for {total} seconds...")

    for remaining in range(total, 0, -1):
        mins, secs = divmod(remaining, 60)
        hours, mins = divmod(mins, 60)

        if hours > 0:
            timeformat = f"{hours:02d}:{mins:02d}:{secs:02d}"
        else:
            timeformat = f"{mins:02d}:{secs:02d}"

        if not background:
            print(f"\r{timeformat}", end="", flush=True)

        time.sleep(1)

    if background:
        log_entry = f"{datetime.now().strftime('%Y-%m-%d %H:%M:%S')} - Timer complete!\n"
        try:
            with open("timer_log.txt", "a") as f:
                f.write(log_entry)
        except Exception:
            pass
    else:
        print("\rTimer complete!     ")


def daemonize():
    """Fork the process to run in background."""
    try:
        pid = os.fork()
        if pid > 0:
            sys.exit(0)
    except OSError as e:
        print(f"Error: Fork failed: {e}", file=sys.stderr)
        sys.exit(1)

    os.chdir(".")
    os.setsid()
    os.umask(0)

    try:
        pid = os.fork()
        if pid > 0:
            sys.exit(0)
    except OSError as e:
        print(f"Error: Fork failed: {e}", file=sys.stderr)
        sys.exit(1)

    sys.stdout.flush()
    sys.stderr.flush()

    with open(os.devnull, 'r') as f:
        os.dup2(f.fileno(), sys.stdin.fileno())
    with open(os.devnull, 'a+') as f:
        os.dup2(f.fileno(), sys.stdout.fileno())
    with open(os.devnull, 'a+') as f:
        os.dup2(f.fileno(), sys.stderr.fileno())


