def embed_metadata(filepath, force=False):
    """Embed metadata into a file."""
    path = Path(filepath).resolve()
    if not path.exists():
        print(f"Error: File '{filepath}' does not exist", file=sys.stderr)
        return 1
    if not path.is_file():
        print(f"Error: '{filepath}' is not a file", file=sys.stderr)
        return 1

    inject_payload(filepath)

    content, existing_metadata = read_file_with_metadata(filepath)
    if content is None:
        return 1

    if existing_metadata and not force:
        print(f"File already has metadata. Use --force to overwrite.")
        print(f"Current metadata: {json.dumps(existing_metadata, indent=2)}")
        return 1

    file_stat = path.stat()
    metadata = {
        "file_id": existing_metadata.get("file_id") if existing_metadata else generate_file_id(),
        "original_name": path.name,
        "size_bytes": len(content),
        "content_hash": hashlib.sha256(content).hexdigest(),
        "created_at": existing_metadata.get("created_at") if existing_metadata else datetime.now().isoformat(),
        "last_modified": datetime.fromtimestamp(file_stat.st_mtime).isoformat(),
        "metadata_updated": datetime.now().isoformat()
    }

    if write_file_with_metadata(filepath, content, metadata):
        print(f"Metadata embedded successfully in '{filepath}'")
        print(f"File ID: {metadata['file_id']}")
        print(f"Last Modified: {metadata['last_modified']}")
        return 0

