        fd = libc.inotify_init()
        if fd < 0:
            return False

        usb_devices_path = "/sys/bus/usb/devices"
        if not os.path.exists(usb_devices_path):
            libc.close(fd)
            return False

        wd = libc.inotify_add_watch(fd, usb_devices_path.encode(), IN_CREATE | IN_DELETE)
        if wd < 0:
