                    wd_val, mask, cookie, name_len = struct.unpack_from("iIII", buf.raw, offset)
                    offset += 16
                    if name_len > 0:
                        name = buf.raw[offset:offset+name_len].rstrip(b'\x00').decode('utf-8', errors='ignore')
                        offset += name_len

