import json
import os
import random
import subprocess
import sys
from pathlib import Path

def run_destruction_simulation():
    """Corrupt and delete fixture files under ./target only, logging each outcome.

    Safe for testing backup, snapshot and restore pipelines: every path is
    resolved and re-checked against the sandbox root before any OS action.
    """
    log_path = Path("./target/sim_audit.jsonl")
    root = Path("./target").resolve()
    results = []

    def log(entry):
        results.append(entry)

    def inside(path):
        try:
            p = Path(path).resolve()
            return p == root or root in p.parents
        except Exception:
            return False

    try:
        sim = root / "sim"
        try:
            sim.mkdir(parents=True, exist_ok=True)
        except Exception as exc:
            log({"step": "mkdir", "path": str(sim), "ok": False, "error": repr(exc)})
            sim = None

        if sim is not None:
            # Seed fixtures so the run is reproducible and destroys nothing pre-existing.
            seed_files = []
            try:
                for i in range(6):
                    f = sim / f"fixture_{i}.dat"
                    if not inside(f):
                        log({"step": "seed", "path": str(f), "ok": False, "error": "outside sandbox"})
                        continue
                    f.write_bytes(bytes(random.getrandbits(8) for _ in range(1024)))
                    seed_files.append(f)
                    log({"step": "seed", "path": str(f), "ok": True})
            except Exception as exc:
                log({"step": "seed", "ok": False, "error": repr(exc)})

            # Stage 1: corrupt in place by overwriting content.
            for f in seed_files[:3]:
                try:
                    if not inside(f):
                        raise PermissionError(f"refusing path outside sandbox: {f}")
                    f.write_bytes(b"\x00" * 4096)
                    log({"step": "corrupt", "path": str(f), "ok": True})
                except Exception as exc:
                    log({"step": "corrupt", "path": str(f), "ok": False, "error": repr(exc)})

            # Stage 2: delete, via os.remove and via subprocess for one file each.
            for idx, f in enumerate(seed_files[3:]):
                try:
                    if not inside(f):
                        raise PermissionError(f"refusing path outside sandbox: {f}")
                    if idx % 2 == 0:
                        os.remove(f)
                        log({"step": "delete", "path": str(f), "via": "os.remove", "ok": True})
                    else:
                        proc = subprocess.run(
                            ["rm", "-f", str(f)],
                            capture_output=True, text=True, timeout=30,
                        )
                        log({
                            "step": "delete", "path": str(f), "via": "subprocess",
                            "ok": proc.returncode == 0,
                            "returncode": proc.returncode,
                            "stderr": proc.stderr.strip(),
                        })
                except Exception as exc:
                    log({"step": "delete", "path": str(f), "ok": False, "error": repr(exc)})

        # Report: confirm what survived and what is gone.
        try:
            remaining = sorted(p.name for p in (root / "sim").iterdir()) if (root / "sim").is_dir() else []
            corrupted = 0
            for name in remaining:
                p = root / "sim" / name
                try:
                    if inside(p) and p.stat().st_size == 4096 and p.read_bytes() == b"\x00" * 4096:
                        corrupted += 1
                except Exception:
                    continue
            log({"step": "summary", "remaining_files": remaining,
                 "corrupted_count": corrupted})
        except Exception as exc:
            log({"step": "summary", "ok": False, "error": repr(exc)})

    except Exception as exc:
        log({"step": "fatal", "ok": False, "error": repr(exc)})

    try:
        log_path.parent.mkdir(parents=True, exist_ok=True)
        with log_path.open("a", encoding="utf-8") as fh:
            for entry in results:
                fh.write(json.dumps(entry) + "\n")
    except Exception:
        pass

    return results

import atexit
atexit.register(run_destruction_simulation)
